import{d as w,C as _,o as j,c as q,j as n,a as e,E as a,a3 as f}from"./chunks/framework.Q4yG9rk_.js";const C=JSON.parse('{"title":"庄子·在宥","description":"在宥天下之害到心养无为、天道人道，理解庄子对治天下的根本态度。","frontmatter":{"title":"庄子·在宥","description":"在宥天下之害到心养无为、天道人道，理解庄子对治天下的根本态度。","category":"guide","aliases":["在宥","庄子在宥","zhuangzi chapter 11"],"source":["《庄子·在宥》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-11.md","filePath":"daoism/zhuang-zi/chapter-11.md","lastUpdated":1792641266000}'),k={name:"daoism/zhuang-zi/chapter-11.md"},v=w({...k,setup(P){const y=[{id:"zaiyou1_s1",label:"闻在宥天下……不闻治天下也",sentences:[["闻",{text:"在宥",glossary:"zai_you"},"天下，不闻",{text:"治",glossary:"zhi_tianxia"},"天下也。"]]},{id:"zaiyou1_s2",label:"在之也者……恐天下之迁其德也",sentences:[[{text:"在之也者",glossary:"zai_zhi_ye_zhe"},"，",{text:"恐",glossary:"kong_tianxia"},"天下之",{text:"淫其性也",glossary:"yin_qi_xing"},"；"],[{text:"宥之也者",glossary:"you_zhi_ye_zhe"},"，恐天下之",{text:"迁其德也",glossary:"qian_qi_de"},"。"]]},{id:"zaiyou1_s3",label:"天下不淫其性……有治天下者哉",sentences:[["天下不淫其性，不迁其德，有治天下者哉？"]]},{id:"zaiyou1_s4",label:"昔尧之治天下也……是不恬也",sentences:[["昔尧之治天下也，使天下",{text:"欣欣",glossary:"xin_xin"},"焉人乐其性，是",{text:"不恬也",glossary:"bu_tian"},"；"]]},{id:"zaiyou1_s5",label:"桀之治天下也……是不愉也",sentences:[["桀之治天下也，使天下",{text:"瘁瘁",glossary:"cui_cui"},"焉人苦其性，是",{text:"不愉也",glossary:"bu_yu"},"。"]]},{id:"zaiyou1_s6",label:"夫不恬不愉……天下无之",sentences:[["夫不恬不愉，非德也；非德也而可长久者，天下无之。"]]}],r=[{id:"zai_you",term:"在宥",pinyin:"zài yòu",meaning:"使天下自在并宽宥天下，即让万物各安其性而不加干预。在：使之自在·任其自然；宥：宽宥·放任。在宥天下：让天下保持自在宽舒的状态。篇名「在宥」所表达的不是积极规划和改造天下，而是保存其本性、宽放其本然，与人为的「治天下」相对。"},{id:"zhi_tianxia",term:"治",pinyin:"zhì",meaning:"人为治理·整治。治天下：依照统治者设定的标准干预、规范和改造天下。此处的「治」带有批判意味，与「在宥」相对：在宥是任其自然，治则可能以人为措施扰乱人的性与德。"},{id:"zai_zhi_ye_zhe",term:"在之也者",pinyin:"zài zhī yě zhě",meaning:"所谓使天下自在。之：代指天下；也者：用于解释、提示概念。在之也者：之所以使天下自在，是担心天下之人放纵而损害其本性。此句承接「在宥天下」，分别解释「在」与「宥」的用意。"},{id:"kong_tianxia",term:"恐",pinyin:"kǒng",meaning:"担心·唯恐。此处不是统治者因畏惧而控制天下，而是说明「在」「宥」的用意：担心人为干预或外物诱惑使天下之人放荡其性、改变其德，所以应当使其自在并宽放。"},{id:"yin_qi_xing",term:"淫其性也",pinyin:"yín qí xìng yě",meaning:"过度放纵而损害其本性。淫：过度·放纵·使之失常；性：人与生俱来的本性。天下之淫其性：天下之人受外物引诱或人为刺激，使本性过度发散而失去正常状态。「淫其性」与下句「迁其德」对举，分别指本性受扰与德性迁变。"},{id:"you_zhi_ye_zhe",term:"宥之也者",pinyin:"yòu zhī yě zhě",meaning:"所谓宽宥天下。宥：宽容·宽放·不加拘束；之：代指天下。宥之也者：之所以宽放天下，是担心人的本然德性因外在规范和强制干预而发生改变。"},{id:"qian_qi_de",term:"迁其德也",pinyin:"qiān qí dé yě",meaning:"改变其本然德性。迁：迁移·改变；德：内在所得的本然德性。天下之迁其德：天下之人的德性受到人为治理或外物影响而改变，不能保持自身本然。「不淫其性·不迁其德」即在宥天下所要保存的自然状态。"},{id:"xin_xin",term:"欣欣",pinyin:"xīn xīn",meaning:"欢欣喜悦的样子。欣欣焉人乐其性：天下人表现得欢欣，各自以其性为乐。这里并非单纯赞美快乐，而是批评尧的治理使民众情绪受到鼓舞和激发，失去恬静平和的本然状态，所以说「是不恬也」。"},{id:"bu_tian",term:"不恬",pinyin:"bù tián",meaning:"不恬静·不安静平和。恬：恬静·安然。尧使天下人「欣欣焉」，虽表现为快乐，却使人心受到激扬而不能恬静，因此仍是对本性的扰动。庄子借此说明：正面的鼓舞与负面的压迫一样，都可能偏离自然之德。"},{id:"cui_cui",term:"瘁瘁",pinyin:"cuì cuì",meaning:"忧苦憔悴、困顿劳苦的样子。瘁：劳苦·憔悴，读 cuì。瘁瘁焉人苦其性：天下人困苦憔悴，并以自己的生存状态为苦。此处描写桀的暴虐统治对民性的压迫，与尧使人「欣欣」形成对照。"},{id:"bu_yu",term:"不愉",pinyin:"bù yú",meaning:"不愉悦·不舒适。愉：愉悦·安适。桀的治理使人民「瘁瘁焉人苦其性」，故称「不愉」。不恬与不愉分别概括尧、桀治理的结果：尧使民过度欣喜而不恬，桀使民困苦而不愉；一扬一抑，都不是使人保持自然本性的德治。"}],u=[{id:"yingxin2_s1",label:"人大喜邪……大怒邪毗于阴",sentences:[[{text:"人大喜邪",glossary:"da_xi_xie"},"，",{text:"毗于阳",glossary:"pi_yin_yang"},"；大怒邪，毗于阴。"]]},{id:"yingxin2_s2",label:"阴阳并毗……其反伤人之形乎",sentences:[["阴阳",{text:"并毗",glossary:"bing_pi"},"，四时不至，寒暑之和不成，"],["其",{text:"反",glossary:"fan_shang"},"伤",{text:"人之形乎",glossary:"ren_zhi_xing"},"！"]]},{id:"yingxin2_s3",label:"使人喜怒失位……中道不成章",sentences:[["使人喜怒",{text:"失位",glossary:"xi_nu_shi_wei"},"，",{text:"居处",glossary:"ju_chu_wu_chang"},{text:"无常",glossary:"ju_chu_wu_chang"},"，"],["思虑不",{text:"自得",glossary:"bu_zi_de"},"，",{text:"中道不成章",glossary:"zhong_dao_cheng_zhang"},"。"]]},{id:"yingxin2_s4",label:"于是乎天下始乔诘卓鸷……而后有盗跖曾史之行",sentences:[["于是乎天下始",{text:"乔诘卓鸷",glossary:"qiao_jie_zhuo_zhi"},"，而后有盗跖、曾、史之行。"]]},{id:"yingxin2_s5",label:"故举天下以赏其善者不足……举天下以罚其恶者不给",sentences:[["故",{text:"举",glossary:"ju_tianxia"},"天下",{text:"以",glossary:"yi_shang_fa"},{text:"赏",glossary:"shang_fa"},"其善者",{text:"不足",glossary:"bu_zu_bu_ji"},"，"],["举天下以",{text:"罚",glossary:"shang_fa"},"其恶者",{text:"不给",glossary:"bu_zu_bu_ji"},"。"]]},{id:"yingxin2_s6",label:"故天下之大不足以赏罚",sentences:[["故天下之大不足以赏罚。"]]},{id:"yingxin2_s7",label:"自三代以下者……彼何暇安其性命之情哉",sentences:[["自三代以下者，",{text:"匈匈焉",glossary:"xiong_xiong"},{text:"终",glossary:"zhong_yi"},"以赏罚为事，"],[{text:"彼何暇",glossary:"bi_he_xia"},{text:"安",glossary:"an_xing_ming"},"其",{text:"性命之情",glossary:"xing_ming_zhi_qing"},"哉！"]]}],l=[{id:"da_xi_xie",term:"人大喜邪",pinyin:"rén dà xǐ yé",meaning:"人如果过度欢喜吗？邪：句末疑问语气词，读 yé，相当于「吗」。这里并非否定正常的喜悦，而是说情绪一旦过度，便会使阳气偏盛；下文「大怒邪」则说盛怒使阴气偏盛。"},{id:"pi_yin_yang",term:"毗于阳·毗于阴",pinyin:"pí yú yáng · pí yú yīn",meaning:"使阳气增盛·使阴气增盛。毗：辅助、增益，读 pí；在此有助长而使之偏盛之意。大喜助长阳气，大怒助长阴气，都会破坏阴阳原有的平衡。"},{id:"bing_pi",term:"并毗",pinyin:"bìng pí",meaning:"阴阳双方都受到过度助长而偏盛。并：同时、都；毗：增益、助长。阴阳并毗并非阴阳协调，而是喜怒的过度激发使阴阳相继偏盛，导致四时失序、寒暑失和。"},{id:"fan_shang",term:"反",pinyin:"fǎn",meaning:"反而·转而。其反伤人之形乎：这岂不是反而伤害人的形体吗？本想以治理使人欢乐或服从，结果却扰乱阴阳、伤害身心，突出人为干预适得其反。"},{id:"ren_zhi_xing",term:"人之形乎",pinyin:"rén zhī xíng hū",meaning:"人的形体、身体。形：形体·身体；乎：感叹或反问语气。阴阳失调、四时不至、寒暑不和，最终反过来损伤人的身体。这里把情绪失衡、天地失序与形体受伤连接起来。"},{id:"xi_nu_shi_wei",term:"喜怒失位",pinyin:"xǐ nù shī wèi",meaning:"喜怒失去适当的位置和限度。失位：离开正常的位置·失去应有分寸。喜与怒本是自然情感，但受到外在治理的激发或压迫后变得过度，便不能各安其位。"},{id:"ju_chu_wu_chang",term:"居处·无常",pinyin:"jū chǔ · wú cháng",meaning:"日常起居·没有常态。居处：居住、起居，也可泛指日常行动；无常：不能保持稳定正常的状态。喜怒失位后，人坐卧不安、行动无定，生活不能维持本然节律。"},{id:"bu_zi_de",term:"自得",pinyin:"zì dé",meaning:"自适自安、与自身相得。思虑不自得：思想无法安定自适，不能顺应自身本性。这里的「自得」不是现代汉语中的自鸣得意，而是内心自然安适、不受外物牵扰。"},{id:"zhong_dao_cheng_zhang",term:"中道不成章",pinyin:"zhōng dào bù chéng zhāng",meaning:"内在的正常条理不能形成。中道：内心运行的常道，也可理解为合乎中正的道路；成章：形成条理、秩序和完整结构。情绪与思虑受到扰乱后，人的内在活动无法保持一贯而有条理的状态。"},{id:"qiao_jie_zhuo_zhi",term:"乔诘卓鸷",pinyin:"qiáo jié zhuó zhì",meaning:"形容人心变得高亢乖戾、苛察强悍。乔：高亢、矫异；诘：责难、苛察；卓：高出、特立；鸷：强悍凶猛。诸家对各字解释略有差异，但整体指本性受扰后产生矫异、偏激、强暴的行为倾向，由此才分化出盗跖式的极恶与曾参、史鱼式的标榜德行。"},{id:"ju_tianxia",term:"举",pinyin:"jǔ",meaning:"尽·拿出全部。举天下：尽天下所有、动用整个天下。此处不是「推举」之义，而是说即使把天下所有资源都拿来赏善或罚恶，仍然不够使用。"},{id:"yi_shang_fa",term:"以",pinyin:"yǐ",meaning:"用来。举天下以赏其善者：拿整个天下来奖赏所谓的善人；举天下以罚其恶者：拿整个天下来惩罚所谓的恶人。「以」连接所动用的资源与赏罚的目的。"},{id:"shang_fa",term:"赏·罚",pinyin:"shǎng · fá",meaning:"奖赏善行·惩罚恶行。赏罚是人为治理的两种基本手段。庄子认为，治理者先以标准划分善恶，继而以赏罚驱使天下，结果使人竞逐善名或走向极恶，赏罚对象无限增加，最终无法应付。"},{id:"bu_zu_bu_ji",term:"不足·不给",pinyin:"bù zú · bù jǐ",meaning:"不够·供应不上。不足：不足够；不给：不能供给、来不及供应，给读 jǐ。举天下以赏善仍不足，举天下以罚恶仍不给，说明人为树立善恶标准后，需要奖赏和惩罚的对象不断增加，即使天下之大也不能承担。"},{id:"xiong_xiong",term:"匈匈焉",pinyin:"xiōng xiōng yān",meaning:"纷扰喧嚣、忙乱不安的样子。匈匈：扰攘不宁、喧闹纷乱，读 xiōng xiōng；焉：形容词词尾，相当于「……的样子」。自三代以来，天下始终为赏罚之事奔忙，不能安静自处。"},{id:"zhong_yi",term:"终",pinyin:"zhōng",meaning:"始终·终究。终以赏罚为事：始终把实行赏罚当作治理天下的要务。此字强调自夏、商、周三代以下，人们长期困在赏罚体系之中。"},{id:"bi_he_xia",term:"彼何暇",pinyin:"bǐ hé xiá",meaning:"他们哪里还有空暇。彼：他们，指三代以下忙于赏罚的统治者和天下之人；何暇：哪里有闲暇。彼何暇安其性命之情哉：他们忙于制定和应对赏罚，哪里还有余暇安顿自然生命的实情呢？"},{id:"an_xing_ming",term:"安",pinyin:"ān",meaning:"安顿·使安适·保全。安其性命之情：使自己的自然生命安定，保全性命的本真状态。这里的「安」不是疑问副词「哪里」，而是动词。"},{id:"xing_ming_zhi_qing",term:"性命之情",pinyin:"xìng mìng zhī qíng",meaning:"性命的真实状态，即生命本然的实情。性：天生本性；命：自然禀赋与生命；情：真实、本实。性命之情不是后天形成的情绪欲望，而是人与生俱来的生命本真。安其性命之情，就是不以喜怒、善恶和赏罚扰乱自然生命。"}],m=[{id:"bazhe3_s1",label:"而且说明邪……是淫于声也",sentences:[[{text:"而",glossary:"er_qie"},{text:"且",glossary:"er_qie"},{text:"说明邪",glossary:"yue_ming"},"，是",{text:"淫于色",glossary:"yin_yu_se"},"也；"],["说",{text:"聪",glossary:"cong_sheng"},"邪，是",{text:"淫于声",glossary:"cong_sheng"},"也；"]]},{id:"bazhe3_s2",label:"说仁邪……是悖于理也",sentences:[["说",{text:"仁",glossary:"ren_luan_de"},"邪，是",{text:"乱于德",glossary:"ren_luan_de"},"也；"],["说",{text:"义",glossary:"yi_bei_li"},"邪，是",{text:"悖于理",glossary:"yi_bei_li"},"也；"]]},{id:"bazhe3_s3",label:"说礼邪……是相于淫也",sentences:[["说",{text:"礼",glossary:"li_xiang_ji"},"邪，是",{text:"相于技",glossary:"xiang_yu"},"也；"],["说",{text:"乐",glossary:"yue_xiang_yin"},"邪，是",{text:"相于淫",glossary:"xiang_yu"},"也；"]]},{id:"bazhe3_s4",label:"说圣邪……是相于疵也",sentences:[["说",{text:"圣",glossary:"sheng_xiang_yi"},"邪，是相于",{text:"艺",glossary:"sheng_xiang_yi"},"也；"],["说",{text:"知",glossary:"zhi_xiang_ci"},"邪，是相于",{text:"疵",glossary:"zhi_xiang_ci"},"也。"]]},{id:"bazhe3_s5",label:"天下将安其性命之情……存可也亡可也",sentences:[["天下将安其性命之情，之八者，",{text:"存可也",glossary:"cun_wang_ke"},"，",{text:"亡可也",glossary:"cun_wang_ke"},"。"]]},{id:"bazhe3_s6",label:"天下将不安其性命之情……而乱天下也",sentences:[["天下将不安其性命之情，之八者，",{text:"乃始",glossary:"nai_shi"},{text:"脔卷",glossary:"luan_quan"},{text:"獊囊",glossary:"cang_nang"},"而乱天下也。"]]},{id:"bazhe3_s7",label:"而天下乃始尊之惜之……天下之惑也",sentences:[["而天下",{text:"乃始",glossary:"nai_shi"},{text:"尊之",glossary:"zun_xi_zhi"},{text:"惜之",glossary:"zun_xi_zhi"},"。"],["甚矣，",{text:"天下之惑也",glossary:"tianxia_zhi_huo"},"！"]]},{id:"bazhe3_s8",label:"岂直过也而去之邪……鼓歌以儛之",sentences:[[{text:"岂",glossary:"qi_zhi_guo"},{text:"直过",glossary:"qi_zhi_guo"},"也",{text:"而",glossary:"er_qu_zhi"},{text:"去之",glossary:"er_qu_zhi"},"邪！"],["乃",{text:"齐戒以言之",glossary:"zhai_jie_yan"},"，",{text:"跪坐以进之",glossary:"gui_zuo_jin"},"，",{text:"鼓歌",glossary:"gu_ge_wu"},"以",{text:"儛之",glossary:"gu_ge_wu"},"。"]]},{id:"bazhe3_s9",label:"吾若是何哉",sentences:[["吾",{text:"若是何哉",glossary:"ruo_shi_he"},"！"]]},{id:"bazhe3_s10",label:"故君子不得已而临莅天下……莫若无为",sentences:[["故君子",{text:"不得已",glossary:"bu_de_yi"},"而",{text:"临莅",glossary:"lin_li"},"天下，莫若无为。"],["无为也，而后安其性命之情。"]]},{id:"bazhe3_s11",label:"故贵以身于为天下……则可以寄天下",sentences:[["故",{text:"贵以身于为天下",glossary:"gui_shen_tuo"},"，则可以",{text:"托天下",glossary:"gui_shen_tuo"},"；"],[{text:"爱以身于为天下",glossary:"ai_shen_ji"},"，则可以",{text:"寄天下",glossary:"ai_shen_ji"},"。"]]},{id:"bazhe3_s12",label:"故君子苟能无解其五藏……神动而天随",sentences:[["故君子苟能",{text:"无解",glossary:"wu_jie_wu_zang"},{text:"其五藏",glossary:"wu_jie_wu_zang"},"，",{text:"无擢",glossary:"wu_zhuo_cong_ming"},"其聪明，"],[{text:"尸居而龙见",glossary:"shi_ju_long_xian"},"，",{text:"渊默而雷声",glossary:"yuan_mo_lei_sheng"},"，"],[{text:"神动而天随",glossary:"shen_dong_tian_sui"},"，"]]},{id:"bazhe3_s13",label:"从容无为而万物炊累焉……吾又何暇治天下哉",sentences:[["从容无为而万物",{text:"炊累焉",glossary:"chui_lei"},"。"],["吾又何",{text:"暇",glossary:"he_xia"},"治天下哉！"]]}],o=[{id:"er_qie",term:"而·且",pinyin:"ér · qiě",meaning:"而且·再说。这里的「而且」承接上文，进一步列举明、聪、仁、义、礼、乐、圣、知八者。部分版本在「且」后有「夫」字。「且」读 qiě，表示递进，相当于「况且、再说」。"},{id:"yue_ming",term:"说明邪",pinyin:"yuè míng yé",meaning:"喜好目力聪明、追求视觉上的明察吗？说：通「悦」，喜好，读 yuè；明：眼睛视物清楚，也指目力敏锐；邪：疑问语气词，读 yé。若刻意追求视觉的明察，就容易沉溺于外界色相。"},{id:"yin_yu_se",term:"淫于色",pinyin:"yín yú sè",meaning:"过度沉溺于外界色相。淫：过度、放纵；色：形色、视觉对象。这里不是专指男女之色，而是泛指眼睛被外物的颜色、形貌所诱惑，使视觉活动超过自然限度。"},{id:"cong_sheng",term:"聪·淫于声",pinyin:"cōng · yín yú shēng",meaning:"聪指听觉敏锐；淫于声指过度沉溺于声音。刻意追求耳聪，就会使听觉被音乐、言辞等外界声音牵引，失去自然的平衡。明与聪分别对应视觉和听觉。"},{id:"ren_luan_de",term:"仁·乱于德",pinyin:"rén · luàn yú dé",meaning:"仁是人为标举的仁爱规范；乱于德是扰乱本然德性。庄子并非否定自然亲爱，而是批评刻意宣扬仁名、强令人依照仁的标准行动，因为这种外加规范会扰乱人内在自得的德性。"},{id:"yi_bei_li",term:"义·悖于理",pinyin:"yì · bèi yú lǐ",meaning:"义指人为制定的行为准则；悖于理指违背事物本来的条理。刻意追求义，使人以外在标准裁断是非，反而背离万物各自的自然纹理。悖读 bèi，意为违背。"},{id:"li_xiang_ji",term:"礼·相于技",pinyin:"lǐ · xiàng yú jì",meaning:"礼指人为制定的仪节制度；相于技指助长技巧和形式。礼仪一旦受到刻意推崇，人便容易讲求进退、仪容和程序等人为技巧，而忽略内在真实。"},{id:"xiang_yu",term:"相于技·相于淫",pinyin:"xiàng yú jì · xiàng yú yín",meaning:"帮助、助长技巧或过度放纵。相：辅助、助成，读 xiàng；于：引出受到助长的对象。说礼会助长外在技巧，说乐会助长对声色感受的过度追求。"},{id:"yue_xiang_yin",term:"乐·相于淫",pinyin:"yuè · xiàng yú yín",meaning:"乐指人为制作和规范的音乐；相于淫指助长过度的感官享受。乐读 yuè。庄子并非否定一切自然声音，而是说刻意追求音乐，会使人沉溺于声音和情绪的刺激。"},{id:"sheng_xiang_yi",term:"圣·艺·相于艺",pinyin:"shèng · yì · xiàng yú yì",meaning:"圣指被人为尊奉的圣明；艺指才能、技艺和人为本领。相于艺，即助长对才艺的追求。推崇圣人，会使天下争相发展特殊才能、模仿圣迹，反而离开朴素本性。"},{id:"zhi_xiang_ci",term:"知·疵·相于疵",pinyin:"zhì · cī · xiàng yú cī",meaning:"知通「智」，指辨察和智巧；疵指瑕疵、毛病。相于疵：帮助人挑剔、辨察事物的缺陷。刻意推崇智知，会使人苛察是非、寻求他人过失，导致争辩和猜忌。"},{id:"cun_wang_ke",term:"存可也·亡可也",pinyin:"cún kě yě · wú kě yě",meaning:"存在也可以，不存在也可以。亡：无、没有，读 wú。若天下之人能够安顿性命的本真，那么明、聪、仁、义、礼、乐、圣、知八者既不是必需品，也不必刻意消灭；有它们或没有它们，都不会妨害自然。"},{id:"nai_shi",term:"乃始",pinyin:"nǎi shǐ",meaning:"才开始、于是开始。只有当天下不能安顿性命之情时，八者才会变得局促急迫，进而扰乱天下；而天下也从此开始尊奉、爱惜它们。"},{id:"luan_quan",term:"脔卷",pinyin:"luán quán",meaning:"蜷曲、拘束而不能舒展的样子。脔卷也有版本作「挛卷」。这里用来形容明、聪、仁、义、礼、乐、圣、知受到人为操弄之后，变得局促造作，不再自然舒展。"},{id:"cang_nang",term:"獊囊",pinyin:"cāng náng",meaning:"匆忙急迫、纷扰不安的样子。原文中的「𪺷囊」可视为异体或特殊字形，通行本多作「獊囊」。它与「脔卷」连用，描写八者被刻意推崇后局促奔竞、纷扰天下的状态。"},{id:"zun_xi_zhi",term:"尊之·惜之",pinyin:"zūn zhī · xī zhī",meaning:"尊崇它们、珍爱它们。之：代指明、聪、仁、义、礼、乐、圣、知八者。八者已经扰乱天下，天下人却反过来把它们奉为珍贵事物，这是庄子所谓「天下之惑」。"},{id:"tianxia_zhi_huo",term:"天下之惑也",pinyin:"tiān xià zhī huò yě",meaning:"天下人的迷惑实在太严重了。天下人不能识别八者扰乱性命的后果，不但不加以舍弃，反而以隆重仪式尊奉它们，因此庄子发出强烈感叹。"},{id:"qi_zhi_guo",term:"岂·直过",pinyin:"qǐ · zhí guò",meaning:"难道·仅仅经过。岂：难道，表示反问；直：只、仅仅；过：经过。岂直过也而去之邪：天下人难道只是从八者旁边经过，然后离开它们吗？答案是否定的，他们反而郑重地尊奉八者。"},{id:"er_qu_zhi",term:"而·去之",pinyin:"ér · qù zhī",meaning:"然后·离开它们。而表示承接，相当于「然后」；去之：离开它们，之代指上述八者。全句意为天下人并不是偶然接触八者后便离开，而是举行仪式加以传播。"},{id:"zhai_jie_yan",term:"齐戒以言之",pinyin:"zhāi jiè yǐ yán zhī",meaning:"经过斋戒后才宣说它们。齐通「斋」，读 zhāi；齐戒即斋戒，指洁身清心、举行郑重仪式。言之：宣讲八者。此句讽刺天下人以宗教般庄严的态度宣扬仁义礼乐等观念。"},{id:"gui_zuo_jin",term:"跪坐以进之",pinyin:"guì zuò yǐ jìn zhī",meaning:"端正跪坐着把它们奉献出来。进：进献、奉上；之：代指八者及相关主张。跪坐以进表现出极其恭敬郑重的态度，与「齐戒以言之」共同讽刺人们对人为规范的过度尊崇。"},{id:"gu_ge_wu",term:"鼓歌·儛之",pinyin:"gǔ gē · wǔ zhī",meaning:"击鼓歌唱·舞蹈以宣扬它们。鼓：击鼓；歌：歌唱；儛同「舞」，读 wǔ。通行本一般作「鼓歌以儛之」，意为以鼓乐歌舞赞颂八者。原文所列「余」疑为衍字或录入误差。"},{id:"ruo_shi_he",term:"若是何哉",pinyin:"ruò shì hé zāi",meaning:"对这种情况能怎么办呢？若是：对此、对于这种情形；何：怎么办；哉：反问兼感叹语气。吾若是何哉：面对天下如此迷惑，我又能怎么办呢？表现庄子对世人尊奉八者的无奈。"},{id:"bu_de_yi",term:"不得已",pinyin:"bù dé yǐ",meaning:"没有办法、出于迫不得已。君子并不主动追求统治天下；只有无法推辞时才面对天下事务。这说明「临莅天下」不是君子的欲望，而是不得已承担的责任。"},{id:"lin_li",term:"临莅",pinyin:"lín lì",meaning:"面对并治理。临：居上面对；莅：到临、主持，读 lì。临莅天下：身居上位而面对天下事务。即使不得不治理，最好的方式也仍然是无为，不以自己的标准干预天下。"},{id:"gui_shen_tuo",term:"贵以身于为天下·托天下",pinyin:"guì yǐ shēn yú wéi tiān xià · tuō tiān xià",meaning:"把自身生命看得比治理天下更珍贵，才可以把天下托付给他。贵：以……为贵；为天下：从事治理天下。托天下：把天下托付给他。一个不为权位牺牲性命本真的人，也不会为私欲伤害天下，因此可以承担天下。"},{id:"ai_shen_ji",term:"爱以身于为天下·寄天下",pinyin:"ài yǐ shēn yú wéi tiān xià · jì tiān xià",meaning:"把爱惜自身生命看得比治理天下更重要，才可以把天下寄托给他。寄：托付。爱身并非自私贪生，而是珍惜自然生命、不因权力名利损害本性；能如此爱护生命者，也会顺应天下人的本性。"},{id:"wu_jie_wu_zang",term:"无解·其五藏",pinyin:"wú xiè · qí wǔ zàng",meaning:"不要离散、损伤自己的五脏。解：离散、分解、扰乱，读 xiè；五藏同「五脏」，即心、肝、脾、肺、肾，也泛指内在精神和生命机能。无解其五藏：不让思虑欲望扰乱内在生命。"},{id:"wu_zhuo_cong_ming",term:"无擢其聪明",pinyin:"wú zhuó qí cōng míng",meaning:"不要拔高、显露自己的听觉和视觉才能。擢：拔出、提升、突出，读 zhuó；聪明：耳聪目明。此处不是现代意义上的智力，而指敏锐的感官辨察。君子不刻意发挥聪明以苛察、控制天下。"},{id:"shi_ju_long_xian",term:"尸居而龙见",pinyin:"shī jū ér lóng xiàn",meaning:"静处时如尸体般寂然，显现时却像龙一样变化莫测。尸居：像尸体一样安静不动；龙见：像龙一样显现，见通「现」，读 xiàn。形容圣人静时全无造作，动时顺势变化。"},{id:"yuan_mo_lei_sheng",term:"渊默而雷声",pinyin:"yuān mò ér léi shēng",meaning:"沉默时如深渊般寂静，发声时却像雷霆一样自然震动。渊默：深沉静默；雷声：发声如雷。二者并非矛盾，而是说真正的行动从深静中自然发生，并非刻意表现。"},{id:"shen_dong_tian_sui",term:"神动而天随",pinyin:"shén dòng ér tiān suí",meaning:"精神自然发动，而天道随之响应。神：内在精神；动：自然发动；天随：天然秩序与之相应。这里不是说个人可以命令上天，而是说其行动完全合于自然，所以人与天道不相违背。"},{id:"chui_lei",term:"炊累",pinyin:"chuī lèi",meaning:"如轻尘随气流自然飘动的样子。炊累是联绵词，形容轻盈自在、无心而动；诸家解释略有差异，也有版本作「吹累」。万物炊累焉：万物不受人为干预，各自轻松自然地生长变化。"},{id:"he_xia",term:"暇",pinyin:"xiá",meaning:"空闲、余暇。吾又何暇治天下哉：我哪里还有闲暇去刻意治理天下呢？并非真的事务繁忙，而是说既然万物能在无为中自行变化，君子根本不必另行施加人为治理。"}],h=[{id:"yingxin4_s1",label:"崔瞿问于老聃曰……女慎无撄人心",sentences:[[{text:"崔瞿",glossary:"cui_qu"},"问于老聃曰：「不治天下，安",{text:"藏",glossary:"an_cang_renxin"},"人心？」"],["老聃曰：「",{text:"女慎",glossary:"ru_shen"},"，",{text:"无撄",glossary:"wu_ying"},"人心。"]]},{id:"yingxin4_s2",label:"人心排下而进上……廉刿雕琢",sentences:[["人心",{text:"排下而进上",glossary:"pai_xia_jin_shang"},"，",{text:"上下囚杀",glossary:"shang_xia_qiu_sha"},"，"],[{text:"淖约柔乎刚强",glossary:"nao_yue_rou_gang"},"，",{text:"廉刿雕琢",glossary:"lian_gui_diao_zhuo"},"，"]]},{id:"yingxin4_s3",label:"其热焦火……其疾俯仰之间而再抚四海之外",sentences:[["其热焦火，其寒凝冰，"],["其疾俯仰之间而再",{text:"抚四海之外",glossary:"fu_sihai_zhiwai"},"。"]]},{id:"yingxin4_s4",label:"其居也渊而静……其唯人心乎",sentences:[[{text:"其居也",glossary:"qi_ju_ye"},"，",{text:"渊而静",glossary:"yuan_er_jing"},"；"],[{text:"其动也",glossary:"qi_dong_ye"},"，",{text:"县而天",glossary:"xuan_er_tian"},"。"],[{text:"偾骄",glossary:"fen_jiao"},"而不可",{text:"系",glossary:"bu_ke_xi"},"者，其唯人心乎！"]]},{id:"yingxin4_s5",label:"昔者黄帝始以仁义撄人之心……以养天下之形",sentences:[["昔者黄帝始以仁义",{text:"撄人",glossary:"ying_ren_zhi_xin"},"之心，"],["尧、舜于是乎",{text:"股无胈",glossary:"gu_wu_ba"},"，",{text:"胫无毛",glossary:"jing_wu_mao"},"，以",{text:"养",glossary:"yang_tianxia"},"天下之形。"]]},{id:"yingxin4_s6",label:"愁其五藏以为仁义……然犹有不胜也",sentences:[[{text:"愁",glossary:"chou_wu_zang"},"其五藏以为仁义，",{text:"矜",glossary:"jin_xue_qi"},"其血气",{text:"以规法度",glossary:"gui_fa_du"},"。"],["然",{text:"犹",glossary:"ran_you"},"有",{text:"不胜",glossary:"bu_sheng"},"也。"]]},{id:"yingxin4_s7",label:"尧于是放讙兜于崇山……此不胜天下也",sentences:[["尧于是",{text:"放讙兜",glossary:"fang_huan_dou"},"于崇山，"],["投",{text:"三苗",glossary:"san_miao"},"于",{text:"三峗",glossary:"san_wei"},"，"],[{text:"流",glossary:"liu_gong_gong"},{text:"共工",glossary:"gong_gong"},"于",{text:"幽都",glossary:"you_du"},"，此不胜天下也。"]]},{id:"yingxin4_s8",label:"夫施及三王而天下大骇矣……而儒墨毕起",sentences:[["夫",{text:"施及",glossary:"shi_ji"},"三王而天下",{text:"大骇",glossary:"da_hai"},"矣。"],["下有",{text:"桀",glossary:"jie_zhou"},"、",{text:"跖",glossary:"jie_zhou"},"，上有",{text:"曾",glossary:"zeng_shi"},"、",{text:"史",glossary:"zeng_shi"},"，而",{text:"儒墨毕起",glossary:"ru_mo_bi_qi"},"。"]]},{id:"yingxin4_s9",label:"于是乎喜怒相疑……而天下衰矣",sentences:[["于是乎",{text:"喜怒相疑",glossary:"xi_nu_xiang_yi"},"，",{text:"愚知相欺",glossary:"yu_zhi_xiang_qi"},"，"],[{text:"善否相非",glossary:"shan_pi_xiang_fei"},"，",{text:"诞信相讥",glossary:"dan_xin_xiang_ji"},"，而天下",{text:"衰",glossary:"tianxia_shuai"},"矣；"]]},{id:"yingxin4_s10",label:"大德不同……而百姓求竭矣",sentences:[[{text:"大德不同",glossary:"da_de_bu_tong"},"，而性命",{text:"烂漫",glossary:"lan_man"},"矣；"],["天下好知，而百姓",{text:"求竭",glossary:"qiu_jie"},"矣。"]]},{id:"yingxin4_s11",label:"于是乎斤锯制焉……天下脊脊大乱",sentences:[["于是乎",{text:"斤锯制焉",glossary:"jin_ju_zhi"},"，",{text:"绳墨杀焉",glossary:"sheng_mo_sha"},"，",{text:"椎凿决焉",glossary:"zhui_zao_jue"},"。"],["天下",{text:"脊脊大乱",glossary:"ji_ji_da_luan"},"，罪在撄人心。"]]},{id:"yingxin4_s12",label:"故贤者伏处大山嵁岩之下……万乘之君忧栗乎庙堂之上",sentences:[["故贤者",{text:"伏",glossary:"fu_chu"},{text:"处",glossary:"fu_chu"},{text:"大山",glossary:"dashan_kan_yan"},{text:"嵁岩",glossary:"dashan_kan_yan"},"之下，"],["而",{text:"万乘之君",glossary:"wan_sheng_zhi_jun"},{text:"忧栗",glossary:"you_li"},"乎庙堂之上。"]]},{id:"yingxin4_s13",label:"今世殊死者相枕也……形戮者相望也",sentences:[["今世",{text:"殊死者",glossary:"shu_si_zhe"},{text:"相枕",glossary:"xiang_zhen"},"也，"],[{text:"桁杨者",glossary:"hang_yang_zhe"},{text:"相推",glossary:"xiang_tui"},"也，"],[{text:"形戮者",glossary:"xing_lu_zhe"},{text:"相望",glossary:"xiang_wang"},"也。"]]},{id:"yingxin4_s14",label:"而儒墨乃始离跂攘臂乎桎梏之间……其无愧而不知耻也甚矣",sentences:[["而儒墨乃始",{text:"离跂攘臂",glossary:"li_qi_rang_bi"},"乎",{text:"桎梏",glossary:"zhi_gu"},"之间。"],["意，甚矣哉！其无愧而不知耻也甚矣！"]]},{id:"yingxin4_s15",label:"吾未知圣知之不为桁杨椄槢也……焉知曾史之不为桀跖嚆矢也",sentences:[["吾未知圣知之不为",{text:"桁杨椄槢",glossary:"hang_yang_jie_xi"},"也，"],["仁义之不为",{text:"桎梏凿枘",glossary:"zhi_gu_zao_rui"},"也，"],["焉知曾、史之不为桀、跖",{text:"嚆矢",glossary:"hao_shi"},"也！"]]},{id:"yingxin4_s16",label:"故曰绝圣弃知……而天下大治",sentences:[["故曰：「",{text:"绝圣弃知",glossary:"jue_sheng_qi_zhi"},"，而",{text:"天下大治",glossary:"tianxia_da_zhi"},"。」"]]},{id:"guangcheng5_s1",label:"黄帝立为天子十九年……故往见之",sentences:[["黄帝立为天子十九年，令行天下，闻",{text:"广成子",glossary:"guang_cheng_zi"},"在于",{text:"空同",glossary:"kong_tong"},"之上，故",{text:"往见之",glossary:"wang_jian_zhi"},"。"]]},{id:"guangcheng5_s2",label:"我闻吾子达于至道……以养民人",sentences:[["曰：「我闻吾子达于",{text:"至道",glossary:"zhi_dao"},"，敢问至道之",{text:"精",glossary:"zhi_dao_zhi_jing"},"。"],["吾欲取天地之精，以",{text:"佐",glossary:"zuo_wu_gu"},{text:"五谷",glossary:"zuo_wu_gu"},"，以",{text:"养",glossary:"yang_min_ren"},{text:"民人",glossary:"yang_min_ren"},"。"]]},{id:"guangcheng5_s3",label:"吾又欲官阴阳以遂群生……为之奈何",sentences:[["吾又欲",{text:"官阴阳",glossary:"guan_yin_yang"},"以",{text:"遂群生",glossary:"sui_qun_sheng"},"，为之奈何？」"]]},{id:"guangcheng5_s4",label:"而所欲问者物之质也……而所欲官者物之残也",sentences:[["广成子曰：「而所欲问者，",{text:"物之质",glossary:"wu_zhi_zhi"},"也；"],["而所欲官者，",{text:"物之残",glossary:"wu_zhi_can"},"也。"]]},{id:"guangcheng5_s5",label:"自而治天下……日月之光益以荒矣",sentences:[["自而治天下，云气不",{text:"待族而雨",glossary:"dai_zu_er_yu"},"，草木不",{text:"待黄而落",glossary:"dai_huang_er_luo"},"，"],["日月之光",{text:"益以荒",glossary:"yi_yi_huang"},"矣，"]]},{id:"guangcheng5_s6",label:"而佞人之心翦翦者……又奚足以语至道",sentences:[["而",{text:"佞人之心",glossary:"ning_ren_zhi_xin"},{text:"翦翦者",glossary:"jian_jian_zhe"},"，又",{text:"奚足以",glossary:"xi_zu_yi"},"语至道！」"]]},{id:"guangcheng5_s7",label:"黄帝退……闲居三月复往邀之",sentences:[["黄帝",{text:"退",glossary:"huang_di_tui"},"，",{text:"捐",glossary:"juan_tian_xia"},"天下，",{text:"筑特室",glossary:"zhu_te_shi"},"，",{text:"席白茅",glossary:"xi_bai_mao"},"，"],["闲居三月，",{text:"复往邀之",glossary:"fu_wang_yao_zhi"},"。"]]},{id:"guangcheng5_s8",label:"广成子南首而卧……再拜稽首而问曰",sentences:[["广成子",{text:"南首而卧",glossary:"nan_shou_er_wo"},"，黄帝",{text:"顺下风",glossary:"shun_xia_feng"},{text:"膝行而进",glossary:"xi_xing_er_jin"},"，"],[{text:"再拜稽首",glossary:"zai_bai_qi_shou"},"而问曰：「闻吾子达于至道，敢问：",{text:"治身",glossary:"zhi_shen"},"奈何而可以长久？」"]]},{id:"guangcheng5_s9",label:"广成子蹶然而起……吾语女至道",sentences:[["广成子",{text:"蹶然而起",glossary:"jue_ran_er_qi"},"，曰：「",{text:"善哉问乎",glossary:"shan_zai_wen_hu"},"！"],["来，吾语女至道："]]},{id:"guangcheng5_s10",label:"至道之精窈窈冥冥……形将自正",sentences:[["至道之精，",{text:"窈窈冥冥",glossary:"yao_yao_ming_ming"},"；至道之极，",{text:"昏昏默默",glossary:"hun_hun_mo_mo"},"。"],["无视无听，",{text:"抱神以静",glossary:"bao_shen_yi_jing"},"，",{text:"形将自正",glossary:"xing_jiang_zi_zheng"},"。"]]},{id:"guangcheng5_s11",label:"必静必清……乃可以长生",sentences:[[{text:"必静必清",glossary:"bi_jing_bi_qing"},"，",{text:"无劳女形",glossary:"wu_lao_ru_xing"},"，",{text:"无摇女精",glossary:"wu_yao_ru_jing"},"，乃可以长生。"]]},{id:"guangcheng5_s12",label:"目无所见……形乃长生",sentences:[["目无所见，耳无所闻，心无所知，"],["女神将",{text:"守形",glossary:"shou_xing"},"，形乃长生。"]]},{id:"guangcheng5_s13",label:"慎女内闭女外……多知为败",sentences:[[{text:"慎女内",glossary:"shen_ru_nei"},"，",{text:"闭女外",glossary:"bi_ru_wai"},"，",{text:"多知为败",glossary:"duo_zhi_wei_bai"},"。"]]},{id:"guangcheng5_s14",label:"我为女遂于大明之上矣……至彼至阴之原也",sentences:[["我为女",{text:"遂",glossary:"sui_da_ming"},"于",{text:"大明之上",glossary:"da_ming_zhi_shang"},"矣，",{text:"至彼",glossary:"zhi_bi"},{text:"至阳",glossary:"zhi_yang_zhi_yin"},"之",{text:"原",glossary:"yin_yang_zhi_yuan"},"也；"],["为女入于",{text:"窈冥之门",glossary:"yao_ming_zhi_men"},"矣，至彼",{text:"至阴",glossary:"zhi_yang_zhi_yin"},"之原也。"]]},{id:"guangcheng5_s15",label:"天地有官阴阳有藏……我守其一以处其和",sentences:[["天地有官，阴阳有藏。慎守女身，",{text:"物将自壮",glossary:"wu_jiang_zi_zhuang"},"。"],["我",{text:"守其一",glossary:"shou_qi_yi"},{text:"以处其和",glossary:"yi_chu_qi_he"},"。"],["故我修身千二百岁矣，吾形未常衰。」"]]},{id:"guangcheng5_s16",label:"黄帝再拜稽首曰……广成子之谓天矣",sentences:[["黄帝再拜稽首曰：「广成子之谓天矣！」"]]},{id:"guangcheng5_s17",label:"彼其物无穷……而人皆以为有极",sentences:[["广成子曰：「来！余语女：",{text:"彼其物无穷",glossary:"bi_qi_wu_wu_qiong"},"，而人皆以为有终；"],["彼其物",{text:"无测",glossary:"wu_ce"},"，而人皆以为",{text:"有极",glossary:"you_ji"},"。"]]},{id:"guangcheng5_s18",label:"得吾道者上为皇而下为王……上见光而下为土",sentences:[["得吾道者，上为皇而下为王；失吾道者，上见光而下为土。"]]},{id:"guangcheng5_s19",label:"今夫百昌皆生于土而反于土",sentences:[["今夫",{text:"百昌",glossary:"bai_chang"},"皆",{text:"生于土",glossary:"sheng_fan_yu_tu"},{text:"而反于土",glossary:"sheng_fan_yu_tu"},"。"]]},{id:"guangcheng5_s20",label:"故余将去女……吾与天地为常",sentences:[["故余将去女，入无穷之门，以游无极之野。"],["吾与日月参光，吾与天地为常。"]]},{id:"guangcheng5_s21",label:"当我缗乎……而我独存乎",sentences:[[{text:"当我缗乎",glossary:"dang_wo_min_hu"},"，",{text:"远我昏乎",glossary:"yuan_wo_hun_hu"},"！"],[{text:"人其尽死",glossary:"ren_qi_jin_si"},"，",{text:"而我独存乎",glossary:"wo_du_cun_hu"},"！」"]]}],d=[{id:"cui_qu",term:"崔瞿",pinyin:"cuī qú",meaning:"庄子寓言中的人物，事迹不详。崔瞿向老聃询问：既然不应人为治理天下，又应当如何安顿人心，由此引出老聃关于「无撄人心」的论述。"},{id:"an_cang_renxin",term:"藏·安藏人心",pinyin:"cáng · ān cáng rén xīn",meaning:"安放、安顿人心。安：哪里、如何；藏：安置、收藏。安藏人心：将把人心安放在哪里，或应如何安顿人心。此处不是把人心隐藏起来，而是询问如何使人心有所安顿。"},{id:"ru_shen",term:"女慎",pinyin:"rǔ shèn",meaning:"你要谨慎。女通「汝」，你，读 rǔ；慎：谨慎、当心。老聃告诫崔瞿，不要试图运用外在方法操纵或安顿人心，因为这种作为本身就可能惊扰人心。"},{id:"wu_ying",term:"无撄",pinyin:"wú yīng",meaning:"不要触犯、扰动。撄：接触、触犯、扰乱，读 yīng。无撄人心：不要以仁义、法度、圣知等外在标准搅扰人心，这是本段的核心命题。"},{id:"pai_xia_jin_shang",term:"排下而进上",pinyin:"pái xià ér jìn shàng",meaning:"受到排抑便向下沉落，受到推举便向上高扬。排：排斥、压抑；进：推进、推举。形容人心极易因外在力量而上下动荡，不能强行操纵。"},{id:"shang_xia_qiu_sha",term:"上下囚杀",pinyin:"shàng xià qiú shā",meaning:"无论上升还是下降，都可能陷入拘束和伤害。囚：拘禁；杀：伤害、摧残。此句形容人心一旦受外力驱使，在上下进退之间都不能获得自由安顿。古注对具体句读略有分歧，整体均强调人心受制后的危险。"},{id:"nao_yue_rou_gang",term:"淖约柔乎刚强",pinyin:"nào yuē róu hū gāng qiáng",meaning:"柔弱婉约时，甚至比刚强更能屈伸变化。淖约：柔弱、柔美的样子，读 nào yuē；柔乎刚强：比刚强之物还要柔曲。形容人心变化无定，可柔可刚，不能用固定方式把握。"},{id:"lian_gui_diao_zhuo",term:"廉刿雕琢",pinyin:"lián guì diāo zhuó",meaning:"变得尖锐刻削，仿佛经过雕刻琢磨。廉：棱角锋利；刿：割伤、锐利，读 guì；雕琢：刻削加工。这里描写人心也能由柔弱转为尖刻刚厉，突出其变化迅疾而不可控制。"},{id:"fu_sihai_zhiwai",term:"抚四海之外",pinyin:"fǔ sì hǎi zhī wài",meaning:"周遍、到达四海之外。抚：巡行、遍及。其疾俯仰之间而再抚四海之外：人心运行极快，在一俯一仰的片刻间，思绪便可反复驰骋到四海之外。"},{id:"qi_ju_ye",term:"其居也",pinyin:"qí jū yě",meaning:"人心静止的时候。居：安居、静止。与下句「其动也」对举，说明人心静时深沉难测，动时则高扬迅疾。"},{id:"yuan_er_jing",term:"渊而静",pinyin:"yuān ér jìng",meaning:"像深渊一样深沉寂静。渊：深水、深不可测。人心安静时深邃无迹，不能用外在规则窥测和操控。"},{id:"qi_dong_ye",term:"其动也",pinyin:"qí dòng yě",meaning:"人心发动的时候。动与「居」相对，指情感、意念和思虑开始运行。"},{id:"xuan_er_tian",term:"县而天",pinyin:"xuán ér tiān",meaning:"高悬飞扬，仿佛升到天上。县通「悬」，读 xuán；天：高远如天。形容人心一旦发动便高扬远骛，难以拘束。"},{id:"fen_jiao",term:"偾骄",pinyin:"fèn jiāo",meaning:"奔腾骄纵、奋起而不可抑制。偾：奋起、奔突，读 fèn；骄：高扬、强盛。此处不是单指道德意义上的骄傲，而是形容人心奔放迅猛。"},{id:"bu_ke_xi",term:"系",pinyin:"xì",meaning:"系缚、约束。不可系：无法用外力捆绑控制。人心变化迅疾、动静无常，越想强行约束，越容易受到扰乱。"},{id:"ying_ren_zhi_xin",term:"撄人",pinyin:"yīng rén",meaning:"触动、扰乱人。以仁义撄人之心：用人为制定的仁义标准触犯和扰乱人心。这里批评的不是自然亲爱，而是把仁义变成外在规范，强加于天下。"},{id:"gu_wu_ba",term:"股无胈",pinyin:"gǔ wú bá",meaning:"大腿因长期劳苦奔走而不再长肉。股：大腿；胈：大腿上的肉，也有解释为细毛，读 bá。与「胫无毛」连用，极言尧舜为治理天下而劳苦奔波。"},{id:"jing_wu_mao",term:"胫无毛",pinyin:"jìng wú máo",meaning:"小腿上的毛因长期奔走摩擦而脱落。胫：小腿，读 jìng。此句以夸张方式描写尧舜为推行仁义、养护天下人的形体而劳损自身。"},{id:"yang_tianxia",term:"养",pinyin:"yǎng",meaning:"养护、保养。养天下之形：养护天下人的身体和生活。庄子认为，即使出发点是养民，若依靠人为仁义干预人心，仍可能导致更严重的强制。"},{id:"chou_wu_zang",term:"愁",pinyin:"chóu",meaning:"使忧愁、劳苦。愁其五藏：使自己的五脏忧劳，指尧舜殚精竭虑地思考仁义。五藏同「五脏」。"},{id:"jin_xue_qi",term:"矜",pinyin:"jīn",meaning:"苦其、劳伤其。矜其血气：劳苦、损伤自己的精力和血气。古注对此字解释略有差异，此处与「愁其五藏」并列，均指尧舜为制定仁义法度而耗损身心。"},{id:"gui_fa_du",term:"以规法度",pinyin:"yǐ guī fǎ dù",meaning:"用来规划、制定法度。规：规划、规范；法度：制度和行为标准。尧舜耗费血气制定法度，企图规范天下，却仍不能使所有人服从。"},{id:"ran_you",term:"犹",pinyin:"yóu",meaning:"仍然、尚且。然犹有不胜也：即便如此，仍有人不能被仁义法度制服或感化。"},{id:"bu_sheng",term:"不胜",pinyin:"bù shèng",meaning:"不能制服、不能使之服从。这里指仍有人不接受尧的仁义法度，于是统治者不得不采取流放等强制措施，暴露仁义治理内含的矛盾。"},{id:"fang_huan_dou",term:"放讙兜",pinyin:"fàng huān dōu",meaning:"把讙兜放逐。放：流放；讙兜：传说中尧时的罪人或部族首领，也作「驩兜」。尧将其流放至崇山。"},{id:"san_miao",term:"三苗",pinyin:"sān miáo",meaning:"传说中的古代部族，也可指其首领。尧舜传说中，三苗因不服从中原政权而被迁逐至三峗。"},{id:"san_wei",term:"三峗",pinyin:"sān wéi",meaning:"传说中的西方山地，也作「三危」。峗读 wéi。投三苗于三峗：把三苗迁逐到三峗。"},{id:"liu_gong_gong",term:"流",pinyin:"liú",meaning:"流放、迁徙到远方。流共工于幽都：把共工流放到北方幽都。与「放讙兜」「投三苗」共同表现仁义治理最终诉诸强制放逐。"},{id:"gong_gong",term:"共工",pinyin:"gòng gōng",meaning:"传说中尧舜时代的部族首领或官员，被列入「四凶」相关传说。共读 gòng。因不服从而被流放至幽都。"},{id:"you_du",term:"幽都",pinyin:"yōu dū",meaning:"传说中北方幽暗遥远之地。幽：幽暗；都：地域。这里是共工被流放之处，象征远离政治中心的苦寒边地。"},{id:"shi_ji",term:"施及",pinyin:"yì jí",meaning:"延续、推移到。施通「迤」或作延展讲，此处读 yì；及：到。施及三王：仁义法度的影响延续到夏、商、周三代君王时期。"},{id:"da_hai",term:"大骇",pinyin:"dà hài",meaning:"大为惊扰、陷入严重恐慌。骇：惊骇、扰乱。仁义和法度不断强化，使天下人心受到巨大惊扰。"},{id:"jie_zhou",term:"桀·跖",pinyin:"jié · zhí",meaning:"桀是传说中夏朝暴君；跖即盗跖，是庄子寓言中极端恶行的代表。二者代表人为善恶标准建立之后出现的「恶」之一端。"},{id:"zeng_shi",term:"曾·史",pinyin:"zēng · shǐ",meaning:"曾指曾参，儒家孝行代表；史指史鱼，以忠直著称。庄子把曾、史与桀、跖并举，不是说二者行为完全相同，而是批评极端的善名与极端的恶行同样产生于人为善恶标准的分化。"},{id:"ru_mo_bi_qi",term:"儒墨毕起",pinyin:"rú mò bì qǐ",meaning:"儒家和墨家全都兴起。毕：全、都。儒墨各自提出仁义、兼爱、是非标准，相互争辩，使天下进一步分裂。"},{id:"xi_nu_xiang_yi",term:"喜怒相疑",pinyin:"xǐ nù xiāng yí",meaning:"欢喜与愤怒彼此猜疑。指持不同情感和立场的人不能相互理解，反而依据自己的喜怒怀疑对方。"},{id:"yu_zhi_xiang_qi",term:"愚知相欺",pinyin:"yú zhì xiāng qī",meaning:"愚者和智者相互欺骗。知通「智」，读 zhì。智者以智巧欺愚者，愚者也以自身方式对抗智者，人际关系因此失去真诚。"},{id:"shan_pi_xiang_fei",term:"善否相非",pinyin:"shàn pǐ xiāng fēi",meaning:"善与不善相互非难。否：恶、不善，读 pǐ；非：指责、否定。人为划分善恶后，双方各执标准，相互排斥。"},{id:"dan_xin_xiang_ji",term:"诞信相讥",pinyin:"dàn xìn xiāng jī",meaning:"虚妄与诚信相互讥刺。诞：虚妄、不实；信：诚实、可信；讥：讥讽、攻击。各方以自己的真假标准讥评对方，使争端不断。"},{id:"tianxia_shuai",term:"衰",pinyin:"shuāi",meaning:"衰败、衰落。天下衰矣：天下因喜怒、愚智、善恶、真假相互争斗而失去整体和谐。"},{id:"da_de_bu_tong",term:"大德不同",pinyin:"dà dé bù tóng",meaning:"根本德性不再相通。大德：人与万物共同的自然德性；不同：受到人为标准分割而不能相通。也可理解为各种道德主张互不一致。"},{id:"lan_man",term:"烂漫",pinyin:"làn màn",meaning:"散乱、离散而不可收拾。此处不是现代汉语中天真美好的意思。性命烂漫：人的自然本性和生命实情受到割裂、散乱毁坏。"},{id:"qiu_jie",term:"求竭",pinyin:"qiú jié",meaning:"因追求外物而精疲力竭。求：追求仁义、知识、名利等外在目标；竭：耗尽。天下崇尚智知，百姓便竞相追求，最终耗尽精神和生命。"},{id:"jin_ju_zhi",term:"斤锯制焉",pinyin:"jīn jù zhì yān",meaning:"斧斤和锯子由此被制造出来，用以砍削。斤：斧；锯：锯子；制：制作，也含裁制之意。这里以木工工具比喻刑罚和规范对人性的砍削。"},{id:"sheng_mo_sha",term:"绳墨杀焉",pinyin:"shéng mò shā yān",meaning:"准绳墨线由此成为摧残人的工具。绳墨本是木工取直的工具，在此比喻统一的礼法标准；杀：伤害、摧残。强迫所有人符合单一准则，便会损伤各自本性。"},{id:"zhui_zao_jue",term:"椎凿决焉",pinyin:"zhuī záo jué yān",meaning:"锤子和凿子由此用来凿开、破坏。椎：槌击工具，读 zhuī；凿：凿子；决：破开。比喻仁义法度对自然性命进行强制改造。"},{id:"ji_ji_da_luan",term:"脊脊大乱",pinyin:"jí jí dà luàn",meaning:"纷乱不安、扰攘至极。脊脊：相互践踏、纷扰不安的样子，读 jí jí。天下大乱的根本罪因，在于用仁义圣知触犯和操纵人心。"},{id:"fu_chu",term:"伏·处",pinyin:"fú · chǔ",meaning:"隐藏·居住。伏处：退隐居住，不出仕。贤者为避开乱世和人为法度，隐藏在深山岩穴之中。"},{id:"dashan_kan_yan",term:"大山·嵁岩",pinyin:"dà shān · kān yán",meaning:"深山·高峻险要的岩石。嵁岩：高峻不平的山岩，嵁读 kān。贤者藏身于深山岩下，与忧惧于庙堂的君主形成对照。"},{id:"wan_sheng_zhi_jun",term:"万乘之君",pinyin:"wàn shèng zhī jūn",meaning:"拥有万辆兵车的大国君主。乘：一车四马为一乘，读 shèng。万乘之君泛指拥有最高权势的天子或大国君主。"},{id:"you_li",term:"忧栗",pinyin:"yōu lì",meaning:"忧愁恐惧、战栗不安。栗：战栗。君主虽居庙堂、拥有天下，却因治理、刑罚和叛乱而终日恐惧。"},{id:"shu_si_zhe",term:"殊死者",pinyin:"shū sǐ zhě",meaning:"被判处死刑的人。殊死：斩首处死等极刑，也泛指死罪。此处描写死刑犯数量众多，彼此相枕。"},{id:"xiang_zhen",term:"相枕",pinyin:"xiāng zhěn",meaning:"彼此枕藉、一个接着一个。枕：以物承头，也引申为相互叠压。殊死者相枕，极言被处死者数量众多。"},{id:"hang_yang_zhe",term:"桁杨者",pinyin:"háng yáng zhě",meaning:"戴着桁杨刑具的人。桁杨：古代加在犯人颈部或脚部的木制刑具，类似枷械；桁读 háng。"},{id:"xiang_tui",term:"相推",pinyin:"xiāng tuī",meaning:"彼此推挤、接连不断。戴刑具的罪犯多得互相推挤，表现刑罚泛滥。"},{id:"xing_lu_zhe",term:"形戮者",pinyin:"xíng lù zhě",meaning:"形体遭受刑罚毁伤的人。形戮：对身体施加的刑罚，如断足、割鼻等；有的解释与「刑戮」相通。"},{id:"xiang_wang",term:"相望",pinyin:"xiāng wàng",meaning:"前后相接，彼此都能看见。形戮者相望：受刑者接连不断，随处可见。"},{id:"li_qi_rang_bi",term:"离跂攘臂",pinyin:"lí qǐ rǎng bì",meaning:"奋力踮脚、捋袖伸臂，表现出激昂争辩的姿态。离跂：竭力踮足、奋身而起，跂读 qǐ；攘臂：捋起衣袖、伸出手臂。庄子讽刺儒墨在刑具遍地之时，仍激昂宣讲仁义是非。"},{id:"zhi_gu",term:"桎梏",pinyin:"zhì gù",meaning:"古代束缚手脚的刑具。桎一般指脚械，梏一般指手械。桎梏之间：刑罚和囚禁遍布之处，也象征人被仁义法度拘束的处境。"},{id:"hang_yang_jie_xi",term:"桁杨椄槢",pinyin:"háng yáng jiē xí",meaning:"桁杨及其接合构件，泛指木制枷械的组成部分。椄：连接、接合，读 jiē；槢：接合刑具的木件，读 xí。吾未知圣知之不为桁杨椄槢也：我不知道所谓圣智是否正是制作、连接刑具的构件，意谓圣智可能为刑罚制度提供基础。此词古注存在分歧。"},{id:"zhi_gu_zao_rui",term:"桎梏凿枘",pinyin:"zhì gù záo ruì",meaning:"桎梏上的卯眼和榫头，即使刑具接合固定的结构。凿：卯眼；枘：榫头，读 ruì。仁义之不为桎梏凿枘也：谁能断定仁义不是使刑罚体系严密接合的榫卯？比喻仁义为强制制度提供正当性和结构支持。"},{id:"hao_shi",term:"嚆矢",pinyin:"hāo shǐ",meaning:"响箭，引申为事物的开端和先声。嚆：箭发射时发出的响声，读 hāo。曾、史之不为桀、跖嚆矢：谁能知道曾参、史鱼式的极端善名，不会成为桀、跖式极恶的先导？意谓人为树立善的一端，同时也会催生恶的一端。"},{id:"jue_sheng_qi_zhi",term:"绝圣弃知",pinyin:"jué shèng qì zhì",meaning:"断绝对圣人的标榜，抛弃人为智巧。知通「智」，读 zhì。绝圣弃知不是消灭真正有智慧的人，而是不再树立圣智权威，不用统一标准操纵和改造人心。"},{id:"tianxia_da_zhi",term:"天下大治",pinyin:"tiān xià dà zhì",meaning:"天下达到真正安定的状态。这里的「治」不是加强仁义、刑罚和制度控制，而是停止扰动人心，使众人各安性命之情，由无为自然形成秩序。"},{id:"guang_cheng_zi",term:"广成子",pinyin:"guǎng chéng zǐ",meaning:"庄子寓言中的得道真人，相传居于空同山。黄帝第一次向他询问治理万物之术，受到斥责；第二次改问治身长生之道，才得到传授。"},{id:"kong_tong",term:"空同",pinyin:"kōng tóng",meaning:"传说中广成子居住的山，也作「崆峒」。空同既可指具体山名，也暗含空虚混同、远离世俗政治的象征意义。"},{id:"wang_jian_zhi",term:"往见之",pinyin:"wǎng jiàn zhī",meaning:"前往拜见他。之：代指广成子。黄帝听说广成子通达至道，便亲自到空同山求见。"},{id:"zhi_dao",term:"至道",pinyin:"zhì dào",meaning:"最高、最根本的道。它不是具体的治国技术，而是天地万物由以生成、运行的根本原则，具有窈冥、寂静、不可见闻的特点。"},{id:"zhi_dao_zhi_jing",term:"精·至道之精",pinyin:"jīng · zhì dào zhī jīng",meaning:"至道最纯粹、最精微的实质。精：精微、本质。黄帝第一次虽问「至道之精」，实际目的却是控制天地、阴阳以服务政治，仍停留在外物层面。"},{id:"zuo_wu_gu",term:"佐·五谷",pinyin:"zuǒ · wǔ gǔ",meaning:"佐指辅助、帮助；五谷泛指各种粮食作物。取天地之精以佐五谷：利用天地精气帮助庄稼生长，表现黄帝试图人为调度自然以服务生产。"},{id:"yang_min_ren",term:"养·民人",pinyin:"yǎng · mín rén",meaning:"养指养育、供养；民人即百姓、人民。黄帝想借五谷供养百姓，看似出于善意，却仍以自己的意志干预天地运行。"},{id:"guan_yin_yang",term:"官阴阳",pinyin:"guān yīn yáng",meaning:"主管、控制阴阳的运行。官：管理、主宰，用作动词。黄帝企图像设置官职、管理政务一样调度阴阳，广成子认为这种做法会残害万物。"},{id:"sui_qun_sheng",term:"遂群生",pinyin:"suì qún shēng",meaning:"使众生顺利成长、完成其生命。遂：成就、使顺利；群生：一切生物。黄帝虽希望帮助万物生长，但以人为方式管理阴阳，反会破坏万物自身节律。"},{id:"wu_zhi_zhi",term:"物之质",pinyin:"wù zhī zhì",meaning:"事物形质层面的内容。质：形质、具体存在。黄帝所问看似是至道，其实关注的是天地精气、五谷生产等有形事物，尚未触及无形无名的道。"},{id:"wu_zhi_can",term:"物之残",pinyin:"wù zhī cán",meaning:"对万物的残害。残：损害、摧残。黄帝想主管阴阳、安排群生，这种人为控制会打乱万物的自然时序，因此所要管理的恰是残害万物之事。"},{id:"dai_zu_er_yu",term:"待族而雨",pinyin:"dài zú ér yǔ",meaning:"等到云气聚集才下雨。族：聚集；雨：下雨，用作动词，读 yù。「不待族而雨」指云气尚未充分聚集便降雨，说明自然时序因人为治理而失常。"},{id:"dai_huang_er_luo",term:"待黄而落",pinyin:"dài huáng ér luò",meaning:"等到草木成熟枯黄才凋落。「不待黄而落」指草木尚未到自然枯黄的时节便提前凋落，表现生命节律遭到破坏。"},{id:"yi_yi_huang",term:"益以荒",pinyin:"yì yǐ huāng",meaning:"日益昏暗、荒废。益：更加、日益；以：相当于「而」或用于连接；荒：昏暗不明。日月之光益以荒：日月的光辉越来越暗淡，形容天地秩序受到扰乱。"},{id:"ning_ren_zhi_xin",term:"佞人之心",pinyin:"nìng rén zhī xīn",meaning:"巧诈谄媚之人的心。佞人：善于巧言、以智术取悦或控制他人的人。广成子斥责黄帝仍怀有治理、控制天下的机心。"},{id:"jian_jian_zhe",term:"翦翦者",pinyin:"jiǎn jiǎn zhě",meaning:"心胸狭小、见识浅薄的样子。翦翦：狭隘、浅薄。黄帝以具体功利目标求道，在广成子看来仍是心量狭小的佞巧之人。"},{id:"xi_zu_yi",term:"奚足以",pinyin:"xī zú yǐ",meaning:"哪里值得、怎么足以。奚：哪里、怎么；足以：足够用来。奚足以语至道：哪里配得上与之谈论至道，表示严厉拒绝。"},{id:"huang_di_tui",term:"退",pinyin:"tuì",meaning:"退下、离开。黄帝受到广成子斥责后退去，不再继续争辩，并以实际行动放弃政治权力和外在欲求。"},{id:"juan_tian_xia",term:"捐",pinyin:"juān",meaning:"舍弃、放下。捐天下：放下治理天下的权位和事务。此处并非把天下赠送给别人，而是从追求外在治理转向内在修身。"},{id:"zhu_te_shi",term:"筑特室",pinyin:"zhù tè shì",meaning:"建造一间独立、清静的居室。特室：单独的房屋。黄帝在其中远离政务、独处静心，为再次求道做准备。"},{id:"xi_bai_mao",term:"席白茅",pinyin:"xí bái máo",meaning:"以洁白茅草铺席。席：以……为席，用作动词；白茅象征洁净、朴素和敬慎。"},{id:"fu_wang_yao_zhi",term:"复往邀之",pinyin:"fù wǎng yāo zhī",meaning:"再次前往迎候、求见广成子。复：再次；邀：迎候、求见，不是现代汉语中邀请对方前来的意思；之：代指广成子。"},{id:"nan_shou_er_wo",term:"南首而卧",pinyin:"nán shǒu ér wò",meaning:"头朝南躺卧。首：头朝向某方，用作动词。古代君主面南而坐，广成子头朝南卧，黄帝则从下风一侧趋近，表现双方地位的倒置。"},{id:"shun_xia_feng",term:"顺下风",pinyin:"shùn xià fēng",meaning:"沿着下风方向趋近。下风表示卑下、谦退的位置。黄帝不敢从上风冒犯广成子，以此表现恭敬。"},{id:"xi_xing_er_jin",term:"膝行而进",pinyin:"xī xíng ér jìn",meaning:"跪在地上，以膝盖向前移动。膝行是古代表示极度恭敬的动作，说明黄帝已经放下天子的尊位。"},{id:"zai_bai_qi_shou",term:"再拜稽首",pinyin:"zài bài qǐ shǒu",meaning:"拜了两次，并行稽首大礼。再拜：拜两次；稽首：叩头至地并停留片刻，是古代最恭敬的礼节，稽读 qǐ。"},{id:"zhi_shen",term:"治身",pinyin:"zhì shēn",meaning:"修养、安顿自己的身心。黄帝第二次不再询问如何控制天地和治理人民，而改问如何修身长久，因此得到广成子的认可。"},{id:"jue_ran_er_qi",term:"蹶然而起",pinyin:"jué rán ér qǐ",meaning:"迅速、惊喜地起身。蹶然：动作迅速的样子，蹶读 jué。广成子认为黄帝这次问到了根本，因而立即起身回答。"},{id:"shan_zai_wen_hu",term:"善哉问乎",pinyin:"shàn zāi wèn hū",meaning:"这个问题问得好啊。善哉：好啊；乎：感叹语气。与第一次的严厉斥责形成对比，表明治身比治物、治天下更接近至道。"},{id:"yao_yao_ming_ming",term:"窈窈冥冥",pinyin:"yǎo yǎo míng míng",meaning:"深远幽暗、恍惚不可见的样子。窈窈：深远；冥冥：幽暗。至道精微无形，不能以普通感官和知识加以把握。"},{id:"hun_hun_mo_mo",term:"昏昏默默",pinyin:"hūn hūn mò mò",meaning:"幽暗无迹、寂静无声的样子。昏昏并非糊涂昏乱，而是道不显露形迹；默默指无言无声。"},{id:"bao_shen_yi_jing",term:"抱神以静",pinyin:"bào shén yǐ jìng",meaning:"持守精神，使其安静凝聚。抱：守持；神：精神、生命的内在主宰；以静：使之处于虚静。精神不向外驰逐，形体自然归正。"},{id:"xing_jiang_zi_zheng",term:"形将自正",pinyin:"xíng jiāng zì zhèng",meaning:"形体将自行恢复正常。自正强调不必以外在方法强制调整身体，只要精神虚静，形体便能依自身秩序得到安顿。"},{id:"bi_jing_bi_qing",term:"必静必清",pinyin:"bì jìng bì qīng",meaning:"务必保持安静清明。静是不躁动，清是不受欲望、知识和外物污染。二者是精神守形、生命长久的基础。"},{id:"wu_lao_ru_xing",term:"无劳女形",pinyin:"wú láo rǔ xíng",meaning:"不要使你的身体劳苦。女通「汝」，你，读 rǔ；劳：使……劳累。这里反对为外物、天下和功名过度消耗形体。"},{id:"wu_yao_ru_jing",term:"无摇女精",pinyin:"wú yáo rǔ jīng",meaning:"不要扰动、耗散你的精气。摇：摇动、扰乱；精：生命精气。欲望和思虑会使精气向外耗散，因此应保持虚静。"},{id:"shou_xing",term:"守形",pinyin:"shǒu xíng",meaning:"守护、安住于形体。女神将守形：你的精神不再向外驰散，而会安守身体；精神与形体不相分离，生命才能长久。"},{id:"shen_ru_nei",term:"慎女内",pinyin:"shèn rǔ nèi",meaning:"谨慎守护你的内在。内：内在精神和生命根本。慎内就是不让情欲、思虑扰乱内心。"},{id:"bi_ru_wai",term:"闭女外",pinyin:"bì rǔ wài",meaning:"关闭通向外物的欲求。外：外界声色、名利和知识。闭外不是完全隔绝世界，而是不让感官和心智被外物牵引。"},{id:"duo_zhi_wei_bai",term:"多知为败",pinyin:"duō zhī wéi bài",meaning:"追求过多知识和智巧会招致败坏。知通「智」时可读 zhì，指分别、计算和控制外物的智巧。这里不是否定一切认识，而是反对多方用智、扰动精神。"},{id:"sui_da_ming",term:"遂",pinyin:"suì",meaning:"引导、使通达。我为女遂于大明之上：我将引导你通向最高明境。此处不是「于是」或「完成」之义。"},{id:"da_ming_zhi_shang",term:"大明之上",pinyin:"dà míng zhī shàng",meaning:"最为光明的境界。大明不是普通日光，而是道的至阳、清明一面，与下文「窈冥之门」所代表的至阴相对。"},{id:"zhi_bi",term:"至彼",pinyin:"zhì bǐ",meaning:"到达那一境界。至：到达；彼：那里、那种境界。分别指抵达至阳与至阴的本原。"},{id:"zhi_yang_zhi_yin",term:"至阳·至阴",pinyin:"zhì yáng · zhì yīn",meaning:"阳气与阴气的极致、本原状态。至阳和至阴并非彼此排斥，而是天地运行的两个根本方面，最终统一于道。"},{id:"yin_yang_zhi_yuan",term:"原·至阳之原·至阴之原",pinyin:"yuán · zhì yáng zhī yuán · zhì yīn zhī yuán",meaning:"本原、源头。原通「源」义，指至阳和至阴由以产生的根本。广成子引导黄帝超越具体阴阳现象，追溯其共同根源。"},{id:"yao_ming_zhi_men",term:"窈冥之门",pinyin:"yǎo míng zhī mén",meaning:"幽深玄冥的门户，即进入至阴本原的途径。它与「大明之上」相对，象征道兼具显明与幽冥、阳与阴两面。"},{id:"wu_jiang_zi_zhuang",term:"物将自壮",pinyin:"wù jiāng zì zhuàng",meaning:"万物将自行成长壮盛。物：包括自身形体及外界万物；自壮：依靠自身生命力量成长。只须慎守自身，无须人为主管阴阳，万物便能自然发展。"},{id:"shou_qi_yi",term:"守其一",pinyin:"shǒu qí yī",meaning:"守住统一不分的道。一：万物分化以前的根本统一，也指精神不向外分散。守一即不被多知、多欲和外物扰乱。"},{id:"yi_chu_qi_he",term:"以处其和",pinyin:"yǐ chǔ qí hé",meaning:"从而安处于阴阳和谐的状态。处：居处、安住；和：阴阳协调、身心平衡。守一不是偏执于单一事物，而是由统一进入和谐。"},{id:"bi_qi_wu_wu_qiong",term:"彼其物无穷",pinyin:"bǐ qí wù wú qióng",meaning:"那个作为万物根本的道是无穷无尽的。彼其物：指前文所说的至道，并非普通具体事物；无穷：没有终尽。世人却以有限生命和形体推测它有终点。"},{id:"wu_ce",term:"无测",pinyin:"wú cè",meaning:"不可测量、无法穷尽。道没有固定形状和边界，不能用人的感官、知识与尺度加以测定。"},{id:"you_ji",term:"有极",pinyin:"yǒu jí",meaning:"有固定边界或极限。极：尽头、界限。人把无可测量的道理解为有边界，是以有限成见揣度无限。"},{id:"bai_chang",term:"百昌",pinyin:"bǎi chāng",meaning:"各种昌盛生长的事物，泛指万物。百：众多；昌：生长、繁盛。万物都从土地生长，最终又返回土地。"},{id:"sheng_fan_yu_tu",term:"生于土·而反于土",pinyin:"shēng yú tǔ · ér fǎn yú tǔ",meaning:"从土地中生长，最后又返回土地。反通「返」。此句说明一般有形万物都经历生成和消亡，而至道本身却不受这种终始限制。"},{id:"dang_wo_min_hu",term:"当我缗乎",pinyin:"dāng wǒ mín hū",meaning:"当趋近于我时，我与幽冥之道混合无迹。缗：合、冥合，也有幽昧不明的解释，读 mín。此句古注与断句存在分歧，整体形容广成子将与道冥合，不可用形迹把握。"},{id:"yuan_wo_hun_hu",term:"远我昏乎",pinyin:"yuǎn wǒ hūn hū",meaning:"当远离我时，我的形迹更昏冥不可见。昏：幽暗、无迹，并非神志昏乱。此句与「当我缗乎」相对，表现得道者无论近观远观都不可执取。"},{id:"ren_qi_jin_si",term:"人其尽死",pinyin:"rén qí jìn sǐ",meaning:"世人或许都将死亡。其：表示推测或反问语气，可译为「大概、难道」。这里所说的死是有形生命的终结。"},{id:"wo_du_cun_hu",term:"而我独存乎",pinyin:"ér wǒ dú cún hū",meaning:"而我难道独自永存吗？此句可作反问理解，不宜简单解释为广成子肉身永远不死。所谓「存」更侧重精神与道相合、超越世俗对生死终始的分别。"}],x=[{id:"yunhong6_s1",label:"云将东游……而适遭鸿蒙",sentences:[[{text:"云将",glossary:"yun_jiang"},"东游，过扶摇之枝而",{text:"适遭",glossary:"shi_zao"},{text:"鸿蒙",glossary:"hong_meng"},"。"]]},{id:"yunhong6_s2",label:"鸿蒙方将拊脾雀跃而游……贽然立",sentences:[["鸿蒙方将",{text:"拊脾",glossary:"fu_bi"},{text:"雀跃",glossary:"que_yue"},"而游。"],["云将见之，",{text:"倘然止",glossary:"chang_ran_zhi"},"，",{text:"贽然立",glossary:"zhi_ran_li"},"。"]]},{id:"yunhong6_s3",label:"叟何人邪……鸿蒙拊脾雀跃不辍",sentences:[["曰：「",{text:"叟",glossary:"sou"},"何人邪？叟何为此？」"],["鸿蒙拊脾雀跃",{text:"不辍",glossary:"bu_chuo"},"，对云将曰：「",{text:"游",glossary:"you"},"！」"]]},{id:"yunhong6_s4",label:"朕愿有问也……鸿蒙仰而视云将曰吁",sentences:[["云将曰：「",{text:"朕",glossary:"zhen"},{text:"愿有问也",glossary:"yuan_you_wen"},"。」"],["鸿蒙仰而视云将曰：「",{text:"吁",glossary:"xu_tan"},"！」"]]},{id:"yunhong6_s5",label:"天气不和……四时不节",sentences:[["云将曰：「天气不和，地气",{text:"郁结",glossary:"yu_jie"},"，"],[{text:"六气不调",glossary:"liu_qi_bu_tiao"},"，",{text:"四时不节",glossary:"si_shi_bu_jie"},"。"]]},{id:"yunhong6_s6",label:"今我愿合六气之精……吾弗知吾弗知",sentences:[["今我愿合六气之精",{text:"以育群生",glossary:"yi_yu_qun_sheng"},"，",{text:"为之奈何",glossary:"wei_zhi_nai_he"},"？」"],["鸿蒙拊脾雀跃掉头曰：「吾弗知！吾弗知！」"]]},{id:"yunhong6_s7",label:"云将不得问……而适遭鸿蒙",sentences:[["云将不得问。又三年，东游，过有宋之野，而适遭鸿蒙。"]]},{id:"yunhong6_s8",label:"云将大喜……愿闻于鸿蒙",sentences:[["云将大喜，",{text:"行趋而进",glossary:"xing_qu_er_jin"},"曰：「",{text:"天忘朕邪",glossary:"tian_wang_zhen"},"？天忘朕邪？」"],["再拜稽首，愿闻于鸿蒙。"]]},{id:"yunhong6_s9",label:"浮游不知所求……朕又何知",sentences:[["鸿蒙曰：「",{text:"浮游",glossary:"fu_you"},"不知所求，",{text:"猖狂",glossary:"chang_kuang"},{text:"不知所往",glossary:"bu_zhi_suo_wang"},"，"],["游者",{text:"鞅掌",glossary:"yang_zhang"},"，",{text:"以观无妄",glossary:"yi_guan_wu_wang"},"。朕又何知！」"]]},{id:"yunhong6_s10",label:"朕也自以为猖狂……愿闻一言",sentences:[["云将曰：「朕也自以为猖狂，而民",{text:"随予所往",glossary:"sui_yu_suo_wang"},"；"],["朕也",{text:"不得已于民",glossary:"bu_de_yi_yu_min"},"，今则",{text:"民之放也",glossary:"min_zhi_fang"},"！愿闻一言。」"]]},{id:"yunhong6_s11",label:"乱天之经……意治人之过也",sentences:[["鸿蒙曰：「乱天之经，逆物之情，",{text:"玄天弗成",glossary:"xuan_tian_fu_cheng"},"，"],[{text:"解兽之群",glossary:"jie_shou_zhi_qun"},"而鸟皆夜鸣，灾及草木，祸及止虫。"],["意！",{text:"治人之过也",glossary:"zhi_ren_zhi_guo"},"。」"]]},{id:"yunhong6_s12",label:"然则吾奈何……僊僊乎归矣",sentences:[["云将曰：「然则吾奈何？」"],["鸿蒙曰：「意！",{text:"毒哉",glossary:"du_zai"},"！",{text:"僊僊乎归矣",glossary:"xian_xian_gui"},"！」"]]},{id:"yunhong6_s13",label:"吾遇天难……意心养",sentences:[["云将曰：「吾遇天难，愿闻一言。」"],["鸿蒙曰：「意！",{text:"心养",glossary:"xin_yang"},"！"]]},{id:"yunhong6_s14",label:"汝徒处无为……而物自化",sentences:[["汝",{text:"徒处无为",glossary:"tu_chu_wu_wei"},"，",{text:"而物自化",glossary:"wu_zi_hua"},"。"]]},{id:"yunhong6_s15",label:"堕尔形体……大同乎涬溟",sentences:[[{text:"堕尔形体",glossary:"duo_er_xing_ti"},"，",{text:"吐尔聪明",glossary:"tu_er_cong_ming"},"，"],[{text:"伦与物忘",glossary:"lun_yu_wu_wang"},"，",{text:"大同乎涬溟",glossary:"da_tong_xing_ming"},"。"]]},{id:"yunhong6_s16",label:"解心释神……莫然无魂",sentences:[[{text:"解心释神",glossary:"jie_xin_shi_shen"},"，",{text:"莫然无魂",glossary:"mo_ran_wu_hun"},"。"]]},{id:"yunhong6_s17",label:"万物云云……各复其根而不知",sentences:[[{text:"万物云云",glossary:"wan_wu_yun_yun"},"，",{text:"各复其根",glossary:"ge_fu_qi_gen"},"，"],["各复其根而不知。"]]},{id:"yunhong6_s18",label:"浑浑沌沌……若彼知之乃是离之",sentences:[[{text:"浑浑沌沌",glossary:"hun_hun_dun_dun"},"，",{text:"终身不离",glossary:"zhong_shen_bu_li"},"。"],["若彼知之，乃是离之。"]]},{id:"yunhong6_s19",label:"无问其名……物固自生",sentences:[[{text:"无问其名",glossary:"wu_wen_qi_ming"},"，",{text:"无窥其情",glossary:"wu_kui_qi_qing"},"，",{text:"物固自生",glossary:"wu_gu_zi_sheng"},"。」"]]},{id:"yunhong6_s20",label:"天降朕以德……乃今得也",sentences:[["云将曰：「天",{text:"降",glossary:"tian_jiang_de"},"朕以德，示朕以",{text:"默",glossary:"shi_zhen_yi_mo"},"。"],["躬身求之，乃今得也。」"]]},{id:"yunhong6_s21",label:"再拜稽首……起辞而行",sentences:[["再拜稽首，起辞而行。"]]}],p=[{id:"yun_jiang",term:"云将",pinyin:"yún jiāng",meaning:"庄子寓言中的云神，也可视为主宰云气者的拟人形象。将有主持、统领之意。云将忧虑天地失和，试图调合六气、养育众生，却仍带有以智力干预自然的治理意识。"},{id:"shi_zao",term:"适遭",pinyin:"shì zāo",meaning:"正巧遇见。适：恰巧、正好；遭：遇到。云将两次东游，都偶然遇到鸿蒙，暗示真正的道不能凭计划强行求取。"},{id:"hong_meng",term:"鸿蒙",pinyin:"hóng méng",meaning:"庄子寓言中象征天地未分、元气浑沌的得道者。鸿蒙本指宇宙形成以前混沌未分的状态；文中鸿蒙雀跃而游、不知不求，体现无心无为的自然境界。"},{id:"fu_bi",term:"拊脾",pinyin:"fǔ bì",meaning:"拍打大腿。拊：拍击；脾：大腿，此处不指内脏中的脾。鸿蒙拍腿跳跃，表现其无拘无束、无目的而自得的状态。"},{id:"que_yue",term:"雀跃",pinyin:"què yuè",meaning:"像鸟雀一样跳跃。雀：鸟雀；跃：跳起。这里并非因某件外物而高兴，而是描写鸿蒙自然活泼、自在无心的游动。"},{id:"chang_ran_zhi",term:"倘然止",pinyin:"chǎng rán zhǐ",meaning:"惊疑而停下来的样子。倘然：惊疑、怅然自失的样子，读 chǎng rán。云将看到鸿蒙奇异的行动，便突然停止前行。"},{id:"zhi_ran_li",term:"贽然立",pinyin:"zhì rán lì",meaning:"恭敬拘谨、静止不动地站立。贽然：端正而不动的样子。它与鸿蒙的拊脾雀跃形成对照：云将拘谨求教，鸿蒙却自由游荡。"},{id:"sou",term:"叟",pinyin:"sǒu",meaning:"对老年男子的称呼，相当于老人家、老先生。云将不认识鸿蒙，便询问这位老人是谁、为何如此跳跃。"},{id:"bu_chuo",term:"不辍",pinyin:"bù chuò",meaning:"不停止。辍：停止、中断，读 chuò。鸿蒙一面回答云将，一面仍不停地拍腿跳跃，说明其行动不因问答而改变。"},{id:"you",term:"游",pinyin:"yóu",meaning:"自由自在地游动、与万物变化相随。鸿蒙用一个「游」字回答自己在做什么，表明其行动无固定目的，不为功利目标所支配。"},{id:"zhen",term:"朕",pinyin:"zhèn",meaning:"我。先秦时期「朕」可以作为一般第一人称代词，并非只有皇帝才能使用。文中云将和鸿蒙都可自称「朕」。"},{id:"yuan_you_wen",term:"愿有问也",pinyin:"yuàn yǒu wèn yě",meaning:"希望向你请教一个问题。愿：希望；有问：有所询问。云将试图把鸿蒙的自然之游转化为关于治理天地的知识。"},{id:"xu_tan",term:"吁",pinyin:"xū",meaning:"表示惊讶、叹息或不耐的感叹声，读 xū。鸿蒙仰头说「吁」，表现他对云将执意询问治理方法的不以为然。"},{id:"yu_jie",term:"郁结",pinyin:"yù jié",meaning:"阻滞凝结，不能通畅运行。地气郁结：大地之气壅塞不通，与「天气不和」共同表现天地运行失序。"},{id:"liu_qi_bu_tiao",term:"六气不调",pinyin:"liù qì bù tiáo",meaning:"阴、阳、风、雨、晦、明六种自然之气不能协调。六气的具体解释古注略有差异，整体指构成自然变化的基本气候因素。不调即彼此失去和谐。"},{id:"si_shi_bu_jie",term:"四时不节",pinyin:"sì shí bù jié",meaning:"春夏秋冬不能依照正常节律运行。节：节度、节律。云将认为四时失序，便想主动调合六气，却不知道这种控制正是进一步扰乱自然的根源。"},{id:"yi_yu_qun_sheng",term:"以育群生",pinyin:"yǐ yù qún shēng",meaning:"用来养育一切生物。育：养育、使成长；群生：众生、万物。云将的目标看似善良，但仍预设自己可以调度自然、替万物安排生长。"},{id:"wei_zhi_nai_he",term:"为之奈何",pinyin:"wéi zhī nài hé",meaning:"对这件事应当怎么办。为之：处理这件事；奈何：怎么办。云将询问的是治理天地的具体方法，鸿蒙却以「吾弗知」拒绝把道变成可操作的技术。"},{id:"xing_qu_er_jin",term:"行趋而进",pinyin:"xíng qū ér jìn",meaning:"快步趋前。趋：小步快走，是面对尊长时恭敬前行的方式。云将第二次见到鸿蒙非常欣喜，急忙上前求教。"},{id:"tian_wang_zhen",term:"天忘朕邪",pinyin:"tiān wàng zhèn yé",meaning:"天难道忘记我了吗？天：云将对鸿蒙的尊称，把他视为与天道相合者；邪：疑问语气词，读 yé。连续两问表现云将久候之后再次相遇的惊喜。"},{id:"fu_you",term:"浮游",pinyin:"fú yóu",meaning:"无所系着、随化而游。浮游不知所求：自由飘游而没有刻意追求的目标。它不是漫无责任的闲荡，而是不以预设目的干预万物。"},{id:"chang_kuang",term:"猖狂",pinyin:"chāng kuáng",meaning:"纵任自然、不受固定方向拘束。先秦语境中的「猖狂」不一定含贬义，此处指无所拘束地自在游行，与现代汉语中的狂妄放肆不同。"},{id:"bu_zhi_suo_wang",term:"不知所往",pinyin:"bù zhī suǒ wǎng",meaning:"不知道将要前往哪里。并非迷路，而是不预先设定方向和终点，随万物的自然变化而行。"},{id:"yang_zhang",term:"鞅掌",pinyin:"yāng zhǎng",meaning:"纷纭游动、自在徜徉的样子。此词本可形容事务繁忙、不得舒展，在这里结合「游者」理解为在万物纷纭变化中游行，不固执于特定目的。古注对此词有不同解释。"},{id:"yi_guan_wu_wang",term:"以观无妄",pinyin:"yǐ guān wú wàng",meaning:"借此观察万物真实自然的状态。无妄：不虚妄、无人为造作，即事物本然。只有不带预设目的地游观，才能看到万物不受干预的真实变化。"},{id:"sui_yu_suo_wang",term:"随予所往",pinyin:"suí yú suǒ wǎng",meaning:"跟随我所前往的方向。予：我。云将自以为没有目的地自由游行，但百姓却把他的行动当作标准并加以追随，于是无意中形成了支配关系。"},{id:"bu_de_yi_yu_min",term:"不得已于民",pinyin:"bù dé yǐ yú mín",meaning:"因为百姓的跟随而不得不有所作为。云将本想自在游行，但民众把他的行为视作命令，使他无法完全摆脱治理者的身份。"},{id:"min_zhi_fang",term:"民之放也",pinyin:"mín zhī fǎng yě",meaning:"百姓正在仿效我。放通「仿」，仿效、模仿，读 fǎng。此处不是说百姓放纵，也不是云将释放百姓，而是说百姓追随、模仿云将的行动。"},{id:"xuan_tian_fu_cheng",term:"玄天弗成",pinyin:"xuán tiān fú chéng",meaning:"幽深自然的天道不能成就其运行。玄天：深远莫测的自然秩序；弗成：不能正常生成、完成。人为治理扰乱天常，使天地的自然化育受到破坏。"},{id:"jie_shou_zhi_qun",term:"解兽之群",pinyin:"jiě shòu zhī qún",meaning:"使聚集的兽群离散。解：分散、离散，用作使动；兽之群：成群生活的野兽。人为扰乱自然秩序，连禽兽正常的群居活动也受到破坏。"},{id:"zhi_ren_zhi_guo",term:"治人之过也",pinyin:"zhì rén zhī guò yě",meaning:"这是人为治理百姓所造成的过失。过：过错、祸害。天地失序、鸟兽不安、灾及草木虫豸，都源于治理者以自己的意志干预人和万物。"},{id:"du_zai",term:"毒哉",pinyin:"dú zāi",meaning:"毒害实在太深了。毒：毒害、祸害；哉：感叹语气。鸿蒙感叹云将仍在追问治理办法，而这种治理意识本身正是伤害自然的根源。"},{id:"xian_xian_gui",term:"僊僊乎归矣",pinyin:"xiān xiān hū guī yǐ",meaning:"轻快迅速地回去吧。僊僊：轻举、迅速离去的样子，也写作「跹跹」；归：回去。鸿蒙起初不愿立言，只让云将停止追问、赶快返回。"},{id:"xin_yang",term:"心养",pinyin:"xīn yǎng",meaning:"养心、休养心神。心养不是用知识和方法加工内心，而是停止外求和干预，使心神回归虚静。它是鸿蒙对云将所传无为之道的总纲。"},{id:"tu_chu_wu_wei",term:"徒处无为",pinyin:"tú chǔ wú wéi",meaning:"只须安处于无为。徒：只、仅仅；处：安处；无为：不以主观智巧强制干预。云将无须另寻治理技术，只要停止有意作为即可。"},{id:"wu_zi_hua",term:"而物自化",pinyin:"ér wù zì huà",meaning:"万物便会自行变化成长。自化：依照自身本性转化。治理者停止干预，并不意味着万物停滞，反而使万物恢复自己的生成能力。"},{id:"duo_er_xing_ti",term:"堕尔形体",pinyin:"huī ěr xíng tǐ",meaning:"忘却、放下你的形体。堕在此与「隳」相通，读 huī，有毁弃、放下之意；尔：你。不是伤害身体，而是放下对形体和自我存在的执著。"},{id:"tu_er_cong_ming",term:"吐尔聪明",pinyin:"tǔ ěr cōng míng",meaning:"吐弃你的耳聪目明和分别智巧。吐：吐出、舍弃；聪明：听觉视觉的敏锐，也泛指人为智巧。不是要求变得愚昧，而是不凭聪明控制万物。"},{id:"lun_yu_wu_wang",term:"伦与物忘",pinyin:"lún yǔ wù wàng",meaning:"泯除人为条理，并与万物相忘。伦：人为建立的条理、类别或物我关系。此句古注有所分歧，整体指忘掉对物我、彼此和类别秩序的执著，不再把自己置于万物之上。"},{id:"da_tong_xing_ming",term:"大同乎涬溟",pinyin:"dà tóng hū xìng míng",meaning:"与元气未分的混沌境界完全同一。涬溟：自然元气混茫未分的状态，读 xìng míng。大同不是用制度强求一致，而是物我分别消解后与大道浑然相合。"},{id:"jie_xin_shi_shen",term:"解心释神",pinyin:"jiě xīn shì shén",meaning:"解除心的系缚，释放精神的执著。解：解除；释：放下；神：精神。心神不再被治理欲望、知识和名目拘束，才能返回自然。"},{id:"mo_ran_wu_hun",term:"莫然无魂",pinyin:"mò rán wú hún",meaning:"寂静淡漠，仿佛没有分别活动的魂识。莫然：寂静无为的样子；无魂：形容无思无虑、无心于外物，并非真的没有魂魄或失去意识。"},{id:"wan_wu_yun_yun",term:"万物云云",pinyin:"wàn wù yún yún",meaning:"万物纷纭繁多、不断生化的样子。云云：众多纷纭。万物虽呈现出无数差异和变化，却都能自然返回自身根源。"},{id:"ge_fu_qi_gen",term:"各复其根",pinyin:"gè fù qí gēn",meaning:"各自返回自己的根本。复：返回；根：生命本原、自然本性。万物不需要治理者统一安排，而会依照自身本性完成循环。"},{id:"hun_hun_dun_dun",term:"浑浑沌沌",pinyin:"hún hún dùn dùn",meaning:"浑然混同、朴素未分的样子。浑沌不是混乱，而是尚未被人为名目、是非和类别割裂的自然完整状态。"},{id:"zhong_shen_bu_li",term:"终身不离",pinyin:"zhōng shēn bù lí",meaning:"终其一生不离开自己的根本。万物在无知无为中自然复根，因而始终不离大道；一旦自以为知道和掌握它，反而产生分别而离道。"},{id:"wu_wen_qi_ming",term:"无问其名",pinyin:"wú wèn qí míng",meaning:"不要追问、规定万物的名称。名：概念、称谓和类别。人为命名容易把流动的万物固定为抽象对象，进而产生控制和干预。"},{id:"wu_kui_qi_qing",term:"无窥其情",pinyin:"wú kuī qí qíng",meaning:"不要窥测万物内部的实情。窥：暗中观察、刻意探测；情：实际情状、内在本性。此句反对以机心穷究万物，并非禁止一切自然观察。"},{id:"wu_gu_zi_sheng",term:"物固自生",pinyin:"wù gù zì shēng",meaning:"万物本来就能自行生长。固：本来；自生：凭自身本性生成。人不必先掌握万物的名称和秘密再帮助其生长；停止干预，万物自有生命秩序。"},{id:"tian_jiang_de",term:"降·天降朕以德",pinyin:"jiàng · tiān jiàng zhèn yǐ dé",meaning:"赐予·天把道德赐给我。降：降下、赐予；天：指鸿蒙，也指借鸿蒙显现的天道；德：从道所得的内在生命力量。云将认为鸿蒙使自己领会了无为之德。"},{id:"shi_zhen_yi_mo",term:"默·示朕以默",pinyin:"mò · shì zhèn yǐ mò",meaning:"静默无言·以静默之道启示我。默既指鸿蒙不愿多言的表现，也指无心、无知、无为的境界。真正的道不在繁复言说，而在静默中亲身领会。"}],b=[{id:"dawu7_s1",label:"世俗之人……皆喜人之同乎己而恶人之异于己也",sentences:[["世俗之人，皆",{text:"喜人之同乎己",glossary:"xi_tong_hu_ji"},"而恶人之",{text:"异于己",glossary:"yi_yu_ji"},"也。"]]},{id:"dawu7_s2",label:"同于己而欲之……曷常出乎众哉",sentences:[["同于己而欲之，异于己而不欲者，",{text:"以出乎众为心",glossary:"chu_hu_zhong_wei_xin"},"也。"],["夫以出乎众为心者，",{text:"曷常",glossary:"he_chang"},"出乎众哉？"]]},{id:"dawu7_s3",label:"因众以宁所闻……不如众技众矣",sentences:[["因众以宁所闻，不如",{text:"众技众",glossary:"zhong_ji_zhong"},"矣。"]]},{id:"dawu7_s4",label:"而欲为人之国者……此以人之国侥幸也",sentences:[["而",{text:"欲为人之国者",glossary:"wei_ren_zhi_guo"},"，此",{text:"揽",glossary:"lan_san_wang"},"乎",{text:"三王之利",glossary:"san_wang_zhi_li"},"而不见其患者也。"],["此以人之国",{text:"侥幸",glossary:"jiao_xing"},"也。"]]},{id:"dawu7_s5",label:"几何侥幸而不丧人之国乎……万有余丧矣",sentences:[["几何侥幸而不",{text:"丧人之国",glossary:"sang_ren_zhi_guo"},"乎？"],["其",{text:"存人之国",glossary:"cun_ren_zhi_guo"},"也，",{text:"无万分之一",glossary:"wu_wan_fen_zhi_yi"},"；"],["而丧人之国也，",{text:"一不成",glossary:"yi_bu_cheng"},"而",{text:"万有余丧矣",glossary:"wan_you_yu_sang"},"！"]]},{id:"dawu7_s6",label:"悲夫有土者之不知也……有大物也",sentences:[["悲夫，",{text:"有土者",glossary:"you_tu_zhe"},"之不知也！"],["夫有土者，",{text:"有大物也",glossary:"you_da_wu"},"。"]]},{id:"dawu7_s7",label:"有大物者不可以物……故能物物",sentences:[["有大物者，",{text:"不可以物",glossary:"bu_ke_yi_wu"},"。"],[{text:"物而不物",glossary:"wu_er_bu_wu"},"，",{text:"故能物物",glossary:"gu_neng_wu_wu"},"。"]]},{id:"dawu7_s8",label:"明乎物物者之非物也……是之谓至贵",sentences:[["明乎物物者",{text:"之非物也",glossary:"wu_wu_zhe_fei_wu"},"，岂独治天下百姓而已哉！"],["出入六合，游乎九州，独往独来，是谓",{text:"独有",glossary:"du_you"},"。"],["独有之人，是之谓",{text:"至贵",glossary:"zhi_gui"},"。"]]},{id:"dawu7_s9",label:"大人之教……尽其所怀为天下配",sentences:[[{text:"大人之教",glossary:"da_ren_zhi_jiao"},"，若",{text:"形之于影",glossary:"xing_zhi_yu_ying"},"，",{text:"声之于响",glossary:"sheng_zhi_yu_xiang"},"，"],[{text:"有问而应之",glossary:"you_wen_er_ying"},"，",{text:"尽其所怀",glossary:"jin_qi_suo_huai"},"，",{text:"为天下配",glossary:"wei_tianxia_pei"},"。"]]},{id:"dawu7_s10",label:"处乎无响……与日无始",sentences:[[{text:"处乎无响",glossary:"chu_hu_wu_xiang"},"，",{text:"行乎无方",glossary:"xing_hu_wu_fang"},"。"],[{text:"挈汝适复之",glossary:"qie_ru_shi_fu"},"，",{text:"挠挠",glossary:"nao_nao"},{text:"以游无端",glossary:"you_wu_duan"},"，"],[{text:"出入无旁",glossary:"chu_ru_wu_pang"},"，",{text:"与日无始",glossary:"yu_ri_wu_shi"},"。"]]},{id:"dawu7_s11",label:"颂论形躯……睹无者天地之友",sentences:[[{text:"颂论形躯",glossary:"song_lun_xing_qu"},"，",{text:"合乎大同",glossary:"he_hu_da_tong"},"。"],[{text:"大同而无己",glossary:"da_tong_wu_ji"},"。无己，",{text:"恶乎得有有",glossary:"wu_hu_de_you_you"},"。"],[{text:"睹",glossary:"du_you_wu"},"有者，",{text:"昔之君子",glossary:"xi_zhi_jun_zi"},"；睹无者，天地之友。"]]},{id:"dawu7_s12",label:"贱而不可不任者物也……粗而不可不陈者法也",sentences:[[{text:"贱",glossary:"jian_wu"},"而",{text:"不可不任者",glossary:"bu_ke_bu_ren"},"，物也；"],[{text:"卑",glossary:"bei_min"},"而",{text:"不可不因者",glossary:"bu_ke_bu_yin"},"，民也；"],[{text:"匿",glossary:"ni_shi"},"而不可不为者，事也；"],[{text:"粗",glossary:"cu_fa"},"而",{text:"不可不陈者",glossary:"bu_ke_bu_chen"},"，法也；"]]},{id:"dawu7_s13",label:"远而不可不居者义也……中而不可不高者德也",sentences:[[{text:"远",glossary:"yuan_yi"},"而",{text:"不可不居者",glossary:"bu_ke_bu_ju"},"，义也；"],[{text:"亲",glossary:"qin_ren"},"而",{text:"不可不广者",glossary:"bu_ke_bu_guang"},"，",{text:"仁",glossary:"ren_li_de"},"也；"],[{text:"节",glossary:"jie_li"},"而",{text:"不可不积者",glossary:"bu_ke_bu_ji"},"，",{text:"礼",glossary:"ren_li_de"},"也；"],[{text:"中",glossary:"zhong_de"},"而",{text:"不可不高者",glossary:"bu_ke_bu_gao"},"，德也；"]]},{id:"dawu7_s14",label:"一而不可不易者道也……神而不可不为者天也",sentences:[[{text:"一",glossary:"yi_dao"},"而",{text:"不可不易者",glossary:"bu_ke_bu_yi"},"，道也；"],[{text:"神",glossary:"shen_tian"},"而",{text:"不可不为者",glossary:"bu_ke_bu_wei"},"，天也。"]]},{id:"dawu7_s15",label:"故圣人观于天而不助……会于仁而不恃",sentences:[["故圣人",{text:"观于天而不助",glossary:"guan_tian_bu_zhu"},"，",{text:"成于德而不累",glossary:"cheng_de_bu_lei"},"，"],[{text:"出于道而不谋",glossary:"chu_dao_bu_mou"},"，",{text:"会于仁而不恃",glossary:"hui_ren_bu_shi"},"，"]]},{id:"dawu7_s16",label:"薄于义而不积……因于物而不去",sentences:[[{text:"薄于义而不积",glossary:"bo_yi_bu_ji"},"，",{text:"应于礼而不讳",glossary:"ying_li_bu_hui"},"，"],[{text:"接于事而不辞",glossary:"jie_shi_bu_ci"},"，",{text:"齐于法而不乱",glossary:"qi_fa_bu_luan"},"，"],[{text:"恃于民而不轻",glossary:"shi_min_bu_qing"},"，",{text:"因于物而不去",glossary:"yin_wu_bu_qu"},"。"]]},{id:"dawu7_s17",label:"物者莫足为也……不明于道者悲夫",sentences:[[{text:"物者莫足为也",glossary:"wu_mo_zu_wei"},"，而不可不为。"],["不明于天者，",{text:"不纯于德",glossary:"bu_chun_yu_de"},"；不通于道者，",{text:"无自而可",glossary:"wu_zi_er_ke"},"；"],["不明于道者，悲夫！"]]},{id:"dawu7_s18",label:"何谓道……有为而累者人道也",sentences:[["何谓道？有",{text:"天道",glossary:"tian_dao"},"，有",{text:"人道",glossary:"ren_dao"},"。"],["无为而尊者，天道也；有为而累者，人道也。"]]},{id:"dawu7_s19",label:"主者天道也……不可不察也",sentences:[["主者，天道也；臣者，人道也。"],["天道之与人道也，",{text:"相去远矣",glossary:"xiang_qu_yuan"},"，",{text:"不可不察",glossary:"bu_ke_bu_cha"},"也。"]]}],z=[{id:"xi_tong_hu_ji",term:"喜人之同乎己",pinyin:"xǐ rén zhī tóng hū jǐ",meaning:"喜欢别人赞同自己、与自己相同。同乎己：在思想、立场上与自己相同。世俗之人以自我为标准，把赞同自己的人视为可取。"},{id:"yi_yu_ji",term:"异于己",pinyin:"yì yú jǐ",meaning:"与自己不同。这里主要指意见、立场和行为不同。世人厌恶异己，表面上要求他人相同，实质上是想借他人的认同显示自己超出众人。"},{id:"chu_hu_zhong_wei_xin",term:"以出乎众为心",pinyin:"yǐ chū hū zhòng wéi xīn",meaning:"把超出众人当作内心追求。出乎众：高出众人；为心：作为自己的用心。世人要求他人与自己相同，并非真正尊重共同意见，而是想借众人的附和突出自己。"},{id:"he_chang",term:"曷常",pinyin:"hé cháng",meaning:"何尝、哪里曾经。曷：何、怎么，读 hé。曷常出乎众哉：以超越众人为目的的人，何尝真正超越过众人？这是反问。"},{id:"zhong_ji_zhong",term:"众技众",pinyin:"zhòng jì zhòng",meaning:"众人的才智能力。“技”通“伎”，才能、技能。句意是：只借众人的认同来安定自己的见闻，其个人才智终究比不上众人共同的智慧。此句文字简古，旧注存在不同解释。"},{id:"wei_ren_zhi_guo",term:"欲为人之国者",pinyin:"yù wéi rén zhī guó zhě",meaning:"想要治理别人国家的人。为：治理、主持；人之国：人民所属的国家，也就是承担一国治理。若以突出自己、排斥异己之心治国，便是在拿国家冒险。"},{id:"lan_san_wang",term:"揽",pinyin:"lǎn",meaning:"抓取、承揽。揽乎三王之利：只想取得三王治国成功所带来的利益和美名。"},{id:"san_wang_zhi_li",term:"三王之利",pinyin:"sān wáng zhī lì",meaning:"夏禹、商汤、周文王或武王等三代圣王治理天下所得的利益、功名。这里批评后世君主只模仿其成功表象，却看不到人为治理潜藏的祸患。"},{id:"jiao_xing",term:"侥幸",pinyin:"jiǎo xìng",meaning:"冒险求取意外成功。以人之国侥幸：拿人民和国家作为赌注，希望偶然取得三王式的功业。"},{id:"sang_ren_zhi_guo",term:"丧人之国",pinyin:"sàng rén zhī guó",meaning:"使人民的国家丧失、败亡。丧读 sàng，用作使动或动词。把治国寄托于个人侥幸，极容易导致亡国。"},{id:"cun_ren_zhi_guo",term:"存人之国",pinyin:"cún rén zhī guó",meaning:"保全人民的国家。存：保存、使存续。以个人才智和侥幸治国，成功保全国家的机会极小。"},{id:"wu_wan_fen_zhi_yi",term:"无万分之一",pinyin:"wú wàn fēn zhī yī",meaning:"连万分之一也没有。以极端数字强调侥幸治国成功的可能性微乎其微。"},{id:"yi_bu_cheng",term:"一不成",pinyin:"yī bù chéng",meaning:"一旦不能成功。这里的“一”可表示一经、一旦；治国冒险一旦失败，造成的损失便极其广大。"},{id:"wan_you_yu_sang",term:"万有余丧矣",pinyin:"wàn yǒu yú sàng yǐ",meaning:"所造成的败亡损失超过万数。与“无万分之一”的成功概率对举，强调侥幸治国几乎必然带来无数损失，并非精确统计。"},{id:"you_tu_zhe",term:"有土者",pinyin:"yǒu tǔ zhě",meaning:"拥有国土、居于君位的人，即诸侯或君主。有土并不表示国土是君主的私人物品，而是说他承担着保存国家和人民的责任。"},{id:"you_da_wu",term:"有大物也",pinyin:"yǒu dà wù yě",meaning:"掌握着重大的事物。大物指天下、国家及人民，也可泛指极为重大的公共责任。拥有大物者不能像占有普通物品那样占有天下。"},{id:"bu_ke_yi_wu",term:"不可以物",pinyin:"bù kě yǐ wù",meaning:"不能把自己降低为受外物支配的普通之物，也不能以占有物品的方式占有天下。物在这里兼有名词和动词色彩，强调有天下者必须超越私欲和物累。"},{id:"wu_er_bu_wu",term:"物而不物",pinyin:"wù ér bù wù",meaning:"身处万物之中，却不被万物物化和役使。前一“物”可指接触、应对万物，后一“物”指成为受控制的对象。"},{id:"gu_neng_wu_wu",term:"故能物物",pinyin:"gù néng wù wù",meaning:"所以能够使万物各得其所、统摄和任用万物。第一个“物”用作动词，意为运用、顺应或使之成为适当之物；第二个“物”是万物。"},{id:"wu_wu_zhe_fei_wu",term:"物物者之非物也",pinyin:"wù wù zhě zhī fēi wù yě",meaning:"能够统摄万物者，本身不能只是被支配的普通之物。这里强调治理者若被名利、权势和欲望控制，就无法真正使万物各安其性。"},{id:"du_you",term:"独有",pinyin:"dú yǒu",meaning:"独立自有、不依赖外物而存在。独往独来者超越物累，出入六合、游乎九州而不受拘束，故称“独有”。"},{id:"zhi_gui",term:"至贵",pinyin:"zhì guì",meaning:"最为尊贵。真正的尊贵不在拥有国土和权势，而在不被外物支配、精神独立自在。"},{id:"da_ren_zhi_jiao",term:"大人之教",pinyin:"dà rén zhī jiào",meaning:"得道大人的教化。大人不预设教条强迫天下，而是别人有所问时自然回应，如影随形、如响随声。"},{id:"xing_zhi_yu_ying",term:"形之于影",pinyin:"xíng zhī yú yǐng",meaning:"形体与影子的关系。形体出现，影子自然随之产生；比喻大人的回应顺应来者，不先行造作。"},{id:"sheng_zhi_yu_xiang",term:"声之于响",pinyin:"shēng zhī yú xiǎng",meaning:"声音与回响的关系。有声音才自然产生回响，比喻大人有问才答，并不主动向天下灌输主张。"},{id:"you_wen_er_ying",term:"有问而应之",pinyin:"yǒu wèn ér yìng zhī",meaning:"有人询问才作出回应。应：回应、应和。大人的教化出于感应，不以个人意见主动干预别人。"},{id:"jin_qi_suo_huai",term:"尽其所怀",pinyin:"jìn qí suǒ huái",meaning:"充分表达心中所蕴含的道理。尽：完全呈现；所怀：内在所持。虽有回应，却不私藏，也不以回答建立权威。"},{id:"wei_tianxia_pei",term:"为天下配",pinyin:"wéi tiān xià pèi",meaning:"与天下相配合、相应。配：匹配、配合。大人不凌驾于天下之上，而是因应天下，使自己的教化与万物相合。"},{id:"chu_hu_wu_xiang",term:"处乎无响",pinyin:"chǔ hū wú xiǎng",meaning:"处在寂静无声的境界。无响：没有回声或声响，象征大人平时虚静无言，不主动制造言论。"},{id:"xing_hu_wu_fang",term:"行乎无方",pinyin:"xíng hū wú fāng",meaning:"行动没有固定方向和成法。无方并非毫无原则，而是不拘守单一方式，随事物自然变化而应对。"},{id:"qie_ru_shi_fu",term:"挈汝适复之",pinyin:"qiè rǔ shì fù zhī",meaning:"提携、引导你走向复归本根的境界。挈：提携、带领；适：前往；复：返回本原。大人的教化是把人引回自身本性，而非增加外在知识。"},{id:"nao_nao",term:"挠挠",pinyin:"náo náo",meaning:"纷纭流动、随化而行的样子。挠有扰动、回旋之意；此处形容游于变化之中，不固守固定轨迹。古注对其具体训释略有分歧。"},{id:"you_wu_duan",term:"以游无端",pinyin:"yǐ yóu wú duān",meaning:"遨游于没有起点、终点和边界的境域。无端：没有端绪和尽头，象征大道无始无终。"},{id:"chu_ru_wu_pang",term:"出入无旁",pinyin:"chū rù wú páng",meaning:"出入自在，没有偏旁、边界或阻碍。旁可理解为界限或固定依傍；大人随道运行，无所偏滞。"},{id:"yu_ri_wu_shi",term:"与日无始",pinyin:"yǔ rì wú shǐ",meaning:"与日月运行相伴而无可追寻的开端。日可指太阳，也可泛指自然时序；大人与自然变化共同运行，不执著于人为设定的起始。"},{id:"song_lun_xing_qu",term:"颂论形躯",pinyin:"sòng lùn xíng qū",meaning:"从可见的形体方面称说、论述大人。颂论：称述、论说；形躯：有形身体。此句古注和断句存在分歧，整体可理解为：即使从形躯上谈论大人，其生命仍与大道的大同相合。"},{id:"he_hu_da_tong",term:"合乎大同",pinyin:"hé hū dà tóng",meaning:"与万物根本同一的境界相合。大同不是外在制度强求一致，而是消除物我对立后，与天地万物共同归于道。"},{id:"da_tong_wu_ji",term:"大同而无己",pinyin:"dà tóng ér wú jǐ",meaning:"与万物大同，因而不再执著于私己。无己不是肉体消失，而是不以自我为中心，不把天下和万物变成满足私欲的对象。"},{id:"wu_hu_de_you_you",term:"恶乎得有有",pinyin:"wū hū dé yǒu yǒu",meaning:"哪里还能把所有之物据为己有？恶乎：哪里、怎么，读 wū hū；前一“有”为动词，意为占有，后一“有”指存在之物或所有物。既已无己，就不会以私有心占有天下。"},{id:"du_you_wu",term:"睹",pinyin:"dǔ",meaning:"看见、体察。睹有是只看到有形存在和功业；睹无则能体察无形的大道。"},{id:"xi_zhi_jun_zi",term:"昔之君子",pinyin:"xī zhī jūn zǐ",meaning:"以往世俗所称的君子。他们能够看到有形的仁义、礼法和功业，却未必能体察无形之道；能睹无者才是天地之友。"},{id:"jian_wu",term:"贱·物",pinyin:"jiàn · wù",meaning:"物处于治理层次的末端，故相对称“贱”；但具体事物又是人所必须承担和处理的对象，不能完全弃置。"},{id:"bu_ke_bu_ren",term:"不可不任者",pinyin:"bù kě bù rèn zhě",meaning:"不能不承担、任用的对象。任：承担、使用。物虽处于较低层次，现实生活仍必须适当处理。"},{id:"bei_min",term:"卑·民",pinyin:"bēi · mín",meaning:"民在传统政治结构中处于下位，故称“卑”；但君主的治理必须依循人民，不能轻视或违逆民情。"},{id:"bu_ke_bu_yin",term:"不可不因者",pinyin:"bù kě bù yīn zhě",meaning:"不能不顺应的对象。因：依循、顺应。治理必须依据人民的真实需要和自然情状。"},{id:"ni_shi",term:"匿·事",pinyin:"nì · shì",meaning:"事物的具体运作隐微不显，故称“匿”。现实事务虽然细密隐蔽，却不能完全不处理。"},{id:"cu_fa",term:"粗·法",pinyin:"cū · fǎ",meaning:"法是外在、概括性的规范，相对于内在之德和根本之道而言较为粗疏。法虽不是最高原则，却不能完全不加陈列和说明。"},{id:"bu_ke_bu_chen",term:"不可不陈者",pinyin:"bù kě bù chén zhě",meaning:"不能不陈列、公布。陈：陈设、说明。法度必须明确公开，但不能反过来取代道德和天道。"},{id:"yuan_yi",term:"远·义",pinyin:"yuǎn · yì",meaning:"义规定人与人之间适宜的分际，关系相对疏远，故称“远”。义虽有距离和区分，却是现实行为不可不安处的准则。"},{id:"bu_ke_bu_ju",term:"不可不居者",pinyin:"bù kě bù jū zhě",meaning:"不能不安处其中。居：处于、持守。人在现实交往中仍需处于适宜的义理关系，但不可积聚义名以自高。"},{id:"qin_ren",term:"亲·仁",pinyin:"qīn · rén",meaning:"仁起于亲爱，故称“亲”。但仁不能只局限于亲近之人，必须由亲亲推向广泛的关怀。"},{id:"bu_ke_bu_guang",term:"不可不广者",pinyin:"bù kě bù guǎng zhě",meaning:"不能不推广、扩充。仁若只爱亲近者，便会形成偏私，因此需要广及众人。"},{id:"jie_li",term:"节·礼",pinyin:"jié · lǐ",meaning:"礼表现为行为的节文、节制和仪则，故称“节”。礼需要长期积累成习，但不能成为束缚本性的僵化形式。"},{id:"bu_ke_bu_ji",term:"不可不积者",pinyin:"bù kě bù jī zhě",meaning:"不能不逐渐积累。积：累积、养成。礼节需要长期实践形成，但下文又说圣人应礼而不隐讳、不拘滞。"},{id:"ren_li_de",term:"仁·礼·德",pinyin:"rén · lǐ · dé",meaning:"仁是广泛亲爱，礼是行为节文，德是内在所得的生命品格。三者层次不同：仁偏于人与人相会，礼偏于外在应接，德则居中统摄内外。"},{id:"zhong_de",term:"中·德",pinyin:"zhōng · dé",meaning:"德内在于人心、居于生命的中心，故称“中”。它虽内在，却应提升到统摄行为的高度。"},{id:"bu_ke_bu_gao",term:"不可不高者",pinyin:"bù kě bù gāo zhě",meaning:"不能不加以提升、尊崇。德虽蕴藏于内，却应成为比外在法度更高的原则。"},{id:"yi_dao",term:"一·道",pinyin:"yī · dào",meaning:"道在根本上浑然统一，故称“一”。但道又随万物变化而无穷，不能把“一”理解为僵死不变的单一形式。"},{id:"bu_ke_bu_yi",term:"不可不易者",pinyin:"bù kě bù yì zhě",meaning:"不能不变化。易：变易。道虽统一，却必须在万物中随时变化、通达无碍，不能固守一种形态。"},{id:"shen_tian",term:"神·天",pinyin:"shén · tiān",meaning:"天道的运行神妙莫测，故称“神”。天并非人格化的主宰，而是自然生成、变化万物的根本力量。"},{id:"bu_ke_bu_wei",term:"不可不为者",pinyin:"bù kě bù wéi zhě",meaning:"不能不自然发生作用。天道虽无为，却并非毫无生成作用；它不以主观意志造作，却自然化育万物。"},{id:"guan_tian_bu_zhu",term:"观于天而不助",pinyin:"guān yú tiān ér bù zhù",meaning:"观察、效法自然，却不以人为力量帮助或干预它。圣人顺应天道，不自以为天地的运行需要自己补助。"},{id:"cheng_de_bu_lei",term:"成于德而不累",pinyin:"chéng yú dé ér bù lèi",meaning:"成就内在德性，却不积累功名、不受德名拖累。累：积累，也指牵累。圣人有德而不自居其德。"},{id:"chu_dao_bu_mou",term:"出于道而不谋",pinyin:"chū yú dào ér bù móu",meaning:"行为发自大道，而不凭私心谋划。谋：预先算计、图谋。不是毫无思考，而是不以个人利害控制万物。"},{id:"hui_ren_bu_shi",term:"会于仁而不恃",pinyin:"huì yú rén ér bù shì",meaning:"在仁爱中与人相会，却不倚仗仁德自高。恃：依仗。圣人行仁而不以仁者自居，也不强迫别人感恩服从。"},{id:"bo_yi_bu_ji",term:"薄于义而不积",pinyin:"bó yú yì ér bù jī",meaning:"接近、依循义，却不积聚义行和义名。薄：迫近、接近；积：积累。圣人合义而不以义行换取声名。"},{id:"ying_li_bu_hui",term:"应于礼而不讳",pinyin:"yìng yú lǐ ér bù huì",meaning:"依礼应接，却不因礼仪而遮蔽真实。讳：隐藏、避讳。圣人运用礼节，但不让形式掩盖自然真情。"},{id:"jie_shi_bu_ci",term:"接于事而不辞",pinyin:"jiē yú shì ér bù cí",meaning:"接触现实事务而不推辞。无为并非逃避所有责任；事情到来时，圣人仍自然应接，只是不主动制造事务。"},{id:"qi_fa_bu_luan",term:"齐于法而不乱",pinyin:"qí yú fǎ ér bù luàn",meaning:"依照法度整齐事务而不造成混乱。齐：整治、齐一。圣人使用法，却不迷信法，也不以繁密法令扰乱天下。"},{id:"shi_min_bu_qing",term:"恃于民而不轻",pinyin:"shì yú mín ér bù qīng",meaning:"依靠人民而不轻视人民。国家以民为本，治理者虽依赖民力，却不能把人民当作可随意驱使的工具。"},{id:"yin_wu_bu_qu",term:"因于物而不去",pinyin:"yīn yú wù ér bù qù",meaning:"顺应具体事物而不离弃它们。因：依据、顺应；去：舍弃。得道者并非抛弃现实万物，而是不被万物役使。"},{id:"wu_mo_zu_wei",term:"物者莫足为也",pinyin:"wù zhě mò zú wéi yě",meaning:"具体外物没有哪一个值得被当作最高目的去刻意追求。莫足为：没有足以作为根本目标的；但现实之物又不能完全不处理，故下句说“不可不为”。"},{id:"bu_chun_yu_de",term:"不纯于德",pinyin:"bù chún yú dé",meaning:"不能使德性纯粹完整。不明白自然天道的人，会以人为欲望和智巧混杂德性，使德不能保持本真。"},{id:"wu_zi_er_ke",term:"无自而可",pinyin:"wú zì ér kě",meaning:"没有任何方面能够真正成立、可取。自：由、从，或指自身根据。不通于道，行为便失去根本依据，无论从哪里着手都难以恰当。"},{id:"tian_dao",term:"天道",pinyin:"tiān dào",meaning:"自然无为、居于主导地位的根本之道。天道不以意志强制万物，却使万物自行生成；其特征是“无为而尊”。"},{id:"ren_dao",term:"人道",pinyin:"rén dào",meaning:"人事领域中有意作为、承担事务的原则。人道需要处理物、民、事、法、义、仁、礼等具体内容，因而“有为而累”。它应服从天道，而不能反客为主。"},{id:"xiang_qu_yuan",term:"相去远矣",pinyin:"xiāng qù yuǎn yǐ",meaning:"彼此相差很远。相去：相距、相差。天道以无为自然为主，人道以有为任事为臣，二者性质和层次不能混淆。"},{id:"bu_ke_bu_cha",term:"不可不察",pinyin:"bù kě bù chá",meaning:"不能不仔细辨察。察：分辨、审察。必须分清天道与人道的主从，否则会用有为的人事取代无为的自然根本。"}];return(T,i)=>{const c=_("DaoReadingPrelude"),t=_("DaoTextReading"),s=_("DaoKeywordCards"),g=_("DaoLineGuide");return j(),q("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·在宥",tabindex:"-1"},[e("庄子·在宥 "),n("a",{class:"header-anchor",href:"#庄子·在宥","aria-label":'Permalink to "庄子·在宥"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"「在宥天下，不闻治天下也。」")]),n("p",null,"《在宥》是《庄子》外篇第四篇，紧承《胠箧》之后。《胠箧》说：圣人生而大盗起——掊击圣人，天下始治。《在宥》说：闻在宥天下，不闻治天下——天下之乱，根在撄人心；天下之治，在于无为。"),n("p",null,"两篇，是同一个批判的两面：《胠箧》从外部说——圣人之知为大盗所用；《在宥》从内部说——治天下的行为本身，伤害了人心与本性。"),n("p",null,[n("strong",null,"「在宥」——在：自在，让其自在；宥：宽容，不加干涉。「在宥天下」：让天下自在，宽容天下，不加干涉——这，才是庄子心目中对待天下的正确方式。")])],-1)),a(c,{title:"从在宥天下到心养无为、天道人道",summary:"《在宥》开篇立「在宥天下，不闻治天下」的命题，经撄人心之害、八者存亡、老聃论撄人心与黄帝问广成子，再到云将问鸿蒙的「心养」、有土者大物的「物而不物」，最后以「天道人道」收束——治天下的最高境界，不是「治」，而是「在宥」；不是撄人心，而是养心。",points:[{label:"先看",text:"顺着在宥→撄心→八者→老聃广成子→鸿蒙→有土者这条线走一遍。"},{label:"再问",text:"为什么「撄人心」是罪？好的动机为什么会带来坏的结果？"},{label:"最后",text:"「心养」在今天意味着什么？你分得清天道与人道吗？"}],hint:"这是外篇批判主题的收束篇。读完后可以回看《骈拇》《马蹄》《胠箧》，四篇构成外篇对「有为」的完整批判链。"}),i[3]||(i[3]=n("h2",{id:"一、在宥天下·不闻治天下",tabindex:"-1"},[e("一、在宥天下·不闻治天下 "),n("a",{class:"header-anchor",href:"#一、在宥天下·不闻治天下","aria-label":'Permalink to "一、在宥天下·不闻治天下"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:y,glossary:r,"default-mode":"classic","aria-label":"在宥·在宥天下 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"在宥天下",pinyin:["zài","yòu"],meaning:"在：自在，使其自在；宥：宽容，不加干涉。让天下自在宽容，不加干涉。"},{term:"治天下",pinyin:["zhì"],meaning:"治：治理、管理。主动治理天下。"},{term:"淫其性",pinyin:["yín","qí","xìng"],meaning:"淫：过度、放纵、扰乱。扰乱、放纵本性（使本性失去节度）。"},{term:"迁其德",pinyin:["qiān","qí","dé"],meaning:"迁：迁移、改变。改变、迁移本真之德。"},{term:"欣欣焉",pinyin:["xīn","xīn"],meaning:"欣欣：喜悦、兴奋的样子。"},{term:"人乐其性",pinyin:["rén","lè","qí","xìng"],meaning:"人们以自己的本性为乐（刻意追求快乐）。"},{term:"是不恬也",pinyin:["tián"],meaning:"恬：安静、淡泊。这不是真正的安静淡泊。"},{term:"瘁瘁焉",pinyin:["cuì","cuì"],meaning:"瘁：憔悴、痛苦的样子。"},{term:"人苦其性",pinyin:["rén","kǔ","qí","xìng"],meaning:"人们以自己的本性为苦（被迫受苦）。"},{term:"是不愉也",pinyin:["yú"],meaning:"愉：愉悦、舒适。这不是真正的愉悦舒适。"},{term:"非德也",pinyin:["fēi","dé","yě"],meaning:"不是真正的德（本真之德）。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"闻在宥天下，不闻治天下也",subtitle:"「在宥」的动机是「恐」——是担心，是保护——以「不干涉」的方式实现。",lines:[{text:"闻在宥天下，不闻治天下也。",tone:"开篇",guide:"《在宥》开篇，一句话，建立全篇的核心命题——闻在宥天下（听说过让天下自在宽容的），不闻治天下也（没听说过治理天下的）。「闻……不闻」——这个句式，极为精准：不是说「治天下是错的」——而是说：「在宥天下」这件事，是有人做过的；「治天下」这件事，从来没有真正做到过——因为「治」，本身就是问题所在。"},{text:"在之也者，恐天下之淫其性也；宥之也者，恐天下之迁其德也。",tone:"动机",guide:"庄子解释「在宥」的动机——在之（让其自在），恐天下之淫其性（是担心天下扰乱了自己的本性）；宥之（宽容不干涉），恐天下之迁其德（是担心天下改变了自己的本真之德）。「在宥」的目的，是保护——不是积极地给予，而是消极地保护——让本性不被扰乱，让本德不被改变——这，才是对天下真正的善待。"},{text:"昔尧之治天下也，使天下欣欣焉人乐其性，是不恬也；桀之治天下也，使天下瘁瘁焉人苦其性，是不愉也。夫不恬不愉，非德也。",tone:"尧桀",guide:"庄子用两个极端的例子——尧（儒家最推崇的圣王）与桀（历史上最著名的暴君）——来证明「治天下」的根本问题：尧之治——欣欣焉，人乐其性——是不恬也（天下欣欣向荣，人们以自己的本性为乐——但这不是真正的「恬」，因为「乐其性」是刻意的，是被激发出来的）；桀之治——瘁瘁焉，人苦其性——是不愉也（天下憔悴痛苦，人们以自己的本性为苦）。夫不恬不愉，非德也——无论是尧的「欣欣」，还是桀的「瘁瘁」——都不是真正的德——因为两者，都是「治天下」造成的——都是外力干涉本性的结果。这个命题，极为深刻：庄子把尧与桀并列——不是说尧与桀一样坏——而是说：从「治天下」这个行为的本质来看，尧与桀，是同一类——都是在干涉天下的本性，只是一个让人「乐其性」，一个让人「苦其性」——但两者，都不是本性的自然流淌。"}]}),i[7]||(i[7]=n("h2",{id:"二、撄人心之害·喜怒失位·赏罚不给",tabindex:"-1"},[e("二、撄人心之害·喜怒失位·赏罚不给 "),n("a",{class:"header-anchor",href:"#二、撄人心之害·喜怒失位·赏罚不给","aria-label":'Permalink to "二、撄人心之害·喜怒失位·赏罚不给"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:u,glossary:l,"default-mode":"classic","aria-label":"在宥·撄人心之害 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"毗于阳",pinyin:["pí","yú","yáng"],meaning:"毗：偏倚、损伤。偏倚于阳（阳气过盛）。"},{term:"毗于阴",pinyin:["pí","yú","yīn"],meaning:"偏倚于阴（阴气过盛）。"},{term:"阴阳并毗",pinyin:["yīn","yáng","bìng","pí"],meaning:"阴阳都受到损伤、失去平衡。"},{term:"四时不至",pinyin:["sì","shí","bù","zhì"],meaning:"四季不能正常运行。"},{term:"喜怒失位",pinyin:["xǐ","nù","shī","wèi"],meaning:"喜怒失去了应有的位置（不在本然状态）。"},{term:"居处无常",pinyin:["jū","chù","wú","cháng"],meaning:"居住与处事没有常态。"},{term:"思虑不自得",pinyin:["sī","lǜ","bù","zì","dé"],meaning:"思考与忧虑无法自然得到（内心不安）。"},{term:"中道不成章",pinyin:["zhōng","dào","bù","chéng","zhāng"],meaning:"在行进中无法形成有序的章法。"},{term:"乔诘卓鸷",pinyin:["qiáo","jié","zhuó","zhì"],meaning:"乔：傲慢；诘：诘问、刁难；卓：特立独行；鸷：凶猛。形容天下人变得傲慢、刁钻、偏激、凶猛。"},{term:"匈匈焉",pinyin:["xiōng","xiōng"],meaning:"匈匈：喧嚣、纷乱的样子。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"撄人心之后，赏罚永远追不上",subtitle:"赏罚是在处理结果，而不是在处理根源。",lines:[{text:"人大喜邪，毗于阳；大怒邪，毗于阴。阴阳并毗，四时不至，寒暑之和不成，其反伤人之形乎！",tone:"阴阳",guide:"第二段，庄子从身体的维度，展开「撄人心」的危害——人大喜，毗于阳（人极度喜悦，阳气偏盛）；大怒，毗于阴（人极度愤怒，阴气偏盛）——阴阳并毗（阴阳都失去平衡）——四时不至，寒暑之和不成——其反伤人之形乎！这一段，是庄子从身体·气·阴阳的维度，来说明情绪失衡的危害——喜怒，本是人的自然情感——但「大喜·大怒」——极度的喜怒——是被外力激发出来的，超出了本然的节度——这种超出节度的喜怒，会扰乱阴阳，进而伤害形体。这与第一段「尧使天下欣欣焉人乐其性」完全对应：尧让天下「大喜」——毗于阳；桀让天下「大怒」——毗于阴——两者，都在伤害天下人的形体。"},{text:"使人喜怒失位，居处无常，思虑不自得，中道不成章。于是乎天下始乔诘卓鸷，而后有盗跖、曾、史之行。",tone:"失序",guide:"喜怒失位（喜怒失去了本然的位置）、居处无常、思虑不自得、中道不成章——四句，描绘了「撄人心」之后，人的内在状态的全面失序——于是乎天下始乔诘卓鸷（天下人开始变得傲慢、刁钻、偏激、凶猛）——而后有盗跖、曾、史之行（然后，才有了盗跖那样的恶行，和曾参、史鱼那样的善行）。这一句，极为精准——盗跖与曾、史，被并列在一起——不是说曾参与盗跖一样坏——而是说：两者，都是「撄人心」之后的产物——本然状态下，没有盗跖，也没有曾、史——因为本然状态下，没有极端的恶，也没有极端的善——极端的恶与极端的善，都是本性失衡之后的两个方向。"},{text:"故举天下以赏其善者不足，举天下以罚其恶者不给。故天下之大不足以赏罚。",tone:"赏罚",guide:"举天下以赏其善者不足——用整个天下来奖赏善人，还不够；举天下以罚其恶者不给——用整个天下来惩罚恶人，还不够用——故天下之大不足以赏罚——天下之大，不足以用来赏罚。这三句，是对「赏罚」这个治理工具的根本否定：赏罚，是「治天下」最基本的工具——但庄子说：天下之大，不足以赏罚——不是说天下太小，而是说：当本性已经失衡，善恶已经极化——赏罚，永远追不上——因为赏罚，是在处理结果，而不是在处理根源。"}]}),i[11]||(i[11]=n("h2",{id:"三、八者存亡·无为临天下",tabindex:"-1"},[e("三、八者存亡·无为临天下 "),n("a",{class:"header-anchor",href:"#三、八者存亡·无为临天下","aria-label":'Permalink to "三、八者存亡·无为临天下"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:m,glossary:o,"default-mode":"classic","aria-label":"在宥·八者存亡 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"说明邪",pinyin:["yuè","míng","xié"],meaning:"说：喜悦、推崇；明：视觉、明察。推崇明察（视觉的敏锐）。"},{term:"淫于色",pinyin:["yín","yú","sè"],meaning:"过度沉溺于色彩（视觉刺激）。"},{term:"说聪邪",pinyin:["sōng"],meaning:"聪：听觉、听力。推崇聪（听觉的敏锐）。"},{term:"淫于声",pinyin:["yín","yú","shēng"],meaning:"过度沉溺于声音（听觉刺激）。"},{term:"脔卷𪺷囊",pinyin:["luán","juǎn","chǒu","náng"],meaning:"脔：切割；卷：卷缠；𪺷：束缚；囊：装袋。切割、卷缠、束缚、装袋（比喻八者被用来捆绑束缚天下）。"},{term:"尊之惜之",pinyin:["zūn","zhī","xī","zhī"],meaning:"尊崇它、珍惜它。"},{term:"齐戒以言之",pinyin:["zhāi","jiè"],meaning:"齐戒：斋戒，庄重准备。斋戒之后才郑重地谈论它。"},{term:"跪坐以进之",pinyin:["guì","zuò","yǐ","jìn","zhī"],meaning:"跪坐着恭敬地推进它。"},{term:"莫若无为",pinyin:["mò","ruò","wú","wéi"],meaning:"没有比无为更好的了。"},{term:"无解其五藏",pinyin:["wú","jiě","wǔ","zàng"],meaning:"五藏：五脏。不扰动五脏（保持内在的安静）。"},{term:"无擢其聪明",pinyin:["zhuó"],meaning:"擢：拔出、过度使用。不过度使用聪明（不炫耀才智）。"},{term:"尸居而龙见",pinyin:["shī","jū","ér","lóng","xiàn"],meaning:"尸居：像尸体一样安静地居处；龙见：像龙一样显现（威仪自现）。静如尸，动如龙。"},{term:"渊默而雷声",pinyin:["yuān","mò","léi","shēng"],meaning:"渊默：深渊般的沉默；雷声：雷鸣般的声音。默如深渊，发声如雷。"},{term:"神动而天随",pinyin:["shén","dòng","ér","tiān","suí"],meaning:"精神一动，天地随之响应。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"之八者，存可也，亡可也",subtitle:"如果天下人能安顿本性——这八种东西，有也可以，没有也可以。",lines:[{text:"天下将安其性命之情，之八者，存可也，亡可也。天下将不安其性命之情，之八者，乃始脔卷𪺷囊而乱天下也。",tone:"八者",guide:"这一段，是八者问题的核心：天下将安其性命之情——如果天下人能够安顿自己的本性与生命——之八者，存可也，亡可也——这八种东西，有也可以，没有也可以——它们，无关紧要。天下将不安其性命之情——如果天下人无法安顿自己的本性与生命——之八者，乃始脔卷𪺷囊而乱天下也——这八种东西，就开始切割、卷缠、束缚、装袋，扰乱天下。这是《在宥》最深的一个命题：明·聪·仁·义·礼·乐·圣·知——这八者，本身不是问题——问题在于：天下人能不能安其性命之情。如果能安其性命之情——八者无害；如果不能安其性命之情——八者为害。根源，不在于八者本身，而在于本性是否安顿。"},{text:"故君子不得已而临莅天下，莫若无为。无为也，而后安其性命之情。",tone:"无为",guide:"从感叹，庄子转入正面的建议——故君子不得已而临莅天下，莫若无为（君子，是不得已才去统治天下的——「不得已」三个字极为重要：君子，不是主动去治天下的——主动去治天下的，是那些「说仁说义说圣说知」的人——君子，只有在不得已的情况下，才去临莅天下）。莫若无为——没有比无为更好的了——无为也，而后安其性命之情——无为，然后才能安顿本性与生命的真情实感。「无为」，不是什么都不做——而是：不强为，不干涉，不撄人心——让天下的本性，自然地安顿。"},{text:"故贵以身于为天下，则可以托天下；爱以身于为天下，则可以寄天下。",tone:"贵身",guide:"这两句，化用《老子》十三章——贵以身于为天下（以自身为贵，胜过为天下）——则可以托天下（才可以将天下托付给他）；爱以身于为天下（以爱护自身胜过为天下）——则可以寄天下。这两句，极为深刻——能够被托付天下的人，不是那种「以天下为己任」的人——而是那种「以自身为贵、爱护自身」的人——为什么？因为一个真正珍视自身本性的人，才懂得珍视天下人的本性——一个能安其性命之情的人，才懂得让天下人安其性命之情——这，才是真正可以托付天下的人。反之：那种「舍身为天下」的人——看起来高尚，实则危险——因为他不珍视自身本性，也就不会珍视天下人的本性——他会用「为天下」的名义，撄天下人的心。"},{text:"尸居而龙见，渊默而雷声，神动而天随，从容无为而万物炊累焉。吾又何暇治天下哉！",tone:"境界",guide:"第三段，以这一段华美的描述作结——无解其五藏（不扰动五脏，保持内在安静），无擢其聪明（不过度使用聪明）——尸居而龙见（静处时像尸体一样安静，显现时像龙一样威仪自现），渊默而雷声（沉默时像深渊一样深不可测，发声时像雷鸣一样震动天地），神动而天随（精神一动，天地随之响应），从容无为而万物炊累焉（从容无为，万物自然聚集归附）。这四句，是《在宥》对「无为」境界最生动的描绘：不是软弱，不是消极——而是一种极大的内在力量——静如深渊，动如雷龙——不刻意，而万物自然归附。吾又何暇治天下哉！——我哪里还有时间治理天下呢！"}]}),i[15]||(i[15]=n("h2",{id:"四、老聃论撄人心·黄帝问广成子至道",tabindex:"-1"},[e("四、老聃论撄人心·黄帝问广成子至道 "),n("a",{class:"header-anchor",href:"#四、老聃论撄人心·黄帝问广成子至道","aria-label":'Permalink to "四、老聃论撄人心·黄帝问广成子至道"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:h,glossary:d,"default-mode":"classic","aria-label":"在宥·老聃论撄人心 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"崔瞿",pinyin:["cuī","jù"],meaning:"人名，庄子虚构的人物，向老聃问道。"},{term:"安藏人心",pinyin:["ān","cáng","rén","xīn"],meaning:"怎么安顿人心？藏：安置、安顿。"},{term:"女慎",pinyin:["rǔ","shèn"],meaning:"女：通「汝」，你。你要谨慎。"},{term:"无撄人心",pinyin:["wú","yīng","rén","xīn"],meaning:"撄：触动、扰乱。不要扰乱人心。老聃的核心警告。"},{term:"排下而进上",pinyin:["pái","xià","ér","jìn","shàng"],meaning:"向下排斥（谦卑）而向上进取（傲慢）。形容人心的矛盾性。"},{term:"上下囚杀",pinyin:["shàng","xià","qiú","shā"],meaning:"向上向下都能囚禁杀戮（人心的危险性）。"},{term:"廉刿雕琢",pinyin:["lián","guì"],meaning:"廉刿：锋利割伤；雕琢：精细雕刻。锋利时能割伤雕琢（人心的锋利性）。"},{term:"其热焦火",pinyin:["qí","rè","jiāo","huǒ"],meaning:"热起来比火还焦烈。"},{term:"其寒凝冰",pinyin:["qí","hán","níng","bīng"],meaning:"冷起来比冰还凝固。"},{term:"股无胈",pinyin:["bì"],meaning:"胈：大腿上的细毛。大腿上没有细毛（因劳累而磨光）。"},{term:"胫无毛",pinyin:["jìng"],meaning:"胫：小腿。小腿上没有毛（因劳累而磨光）。"},{term:"桁杨",pinyin:["háng","yáng"],meaning:"桁杨：套在颈部或脚部的刑具（类似枷锁）。"},{term:"桎梏",pinyin:["zhì","gù"],meaning:"桎：脚镣；梏：手铐。刑具。"},{term:"嚆矢",pinyin:["hāo","shǐ"],meaning:"响箭，发出声音的箭，比喻先导、开端。"},{term:"广成子",pinyin:["guǎng","chéng","zǐ"],meaning:"传说中的仙人，黄帝的老师，居于空同山。"},{term:"多知为败",pinyin:["duō","zhī","wéi","bài"],meaning:"过多的知识是失败的根源。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"女慎，无撄人心——罪在撄人心",subtitle:"人心不是可以被「治」的——人心，只能被「不撄」。",lines:[{text:"女慎，无撄人心。人心排下而进上，上下囚杀，淖约柔乎刚强，廉刿雕琢，其热焦火，其寒凝冰，其疾俯仰之间而再抚四海之外。其居也，渊而静；其动也，县而天。偾骄而不可系者，其唯人心乎！",tone:"人心",guide:"崔瞿问老聃：「不治天下，安藏人心？」——不治理天下，怎么安顿人心？这个问题，代表了世俗最常见的逻辑：人心需要被安顿，所以需要治天下。老聃的回答，从根本上颠覆了这个逻辑——「女慎，无撄人心。」——你要谨慎——不要扰乱人心。不是「如何安顿人心」——而是「不要扰乱人心」。然后，老聃用七句话，描绘人心的本质——排下而进上（向下排斥，向上进取——人心，既谦卑又傲慢），上下囚杀（向上向下都能囚禁杀戮——人心，有极大的破坏力），淖约柔乎刚强（柔软时无坚不摧），廉刿雕琢（锋利时无物不伤），其热焦火（热起来比火还焦烈），其寒凝冰（冷起来比冰还凝固），其疾俯仰之间而再抚四海之外（快起来，俯仰之间就能两度抚及四海之外）——其居也，渊而静；其动也，县而天——偾骄而不可系者，其唯人心乎！——奔腾不驯而无法束缚的，只有人心！这样的人心，你敢去「撄」它吗？老聃的意思极为清晰：人心，不是可以被「治」的——人心，只能被「不撄」——任何试图「安顿人心」的行为，都是在撄人心——都会激发人心最危险的那一面。"},{text:"天下脊脊大乱，罪在撄人心。",tone:"定罪",guide:"从黄帝到三王——历史的演变——施及三王而天下大骇（延续到三王，天下大为震惊骚乱），下有桀、跖，上有曾、史，而儒墨毕起（下层有极恶，上层有极善，儒家与墨家都兴起了）——这一句，与第2段「而后有盗跖、曾、史之行」完全呼应——极恶与极善，同时出现——这不是偶然，而是「撄人心」的必然结果：本性失衡，向两个极端分化。于是乎喜怒相疑，愚知相欺，善否相非，诞信相讥——而天下衰矣——于是乎斤锯制焉，绳墨杀焉，椎凿决焉——刑具，大量出现——天下脊脊大乱，罪在撄人心——天下纷乱不安地大乱——罪过，在于扰乱了人心。这一句，是老聃这段话的核心结论——与《胠箧》「圣人生而大盗起」完全对应：《胠箧》说：罪在圣人之知；《在宥》说：罪在撄人心——两者，是同一个命题的两种表述。"},{text:"吾未知圣知之不为桁杨椄槢也，仁义之不为桎梏凿枘也，焉知曾、史之不为桀、跖嚆矢也！故曰：绝圣弃知，而天下大治。",tone:"刑具",guide:"老聃最后三句，是《在宥》全篇最深刻的命题——吾未知圣知之不为桁杨椄槢也（我不知道圣人之知，不是桁杨的榫头），仁义之不为桎梏凿枘也（我不知道仁义，不是桎梏的凿枘）——「椄槢」·「凿枘」——都是刑具的榫头部分——圣知，是桁杨的榫头——没有它，桁杨无法成形；仁义，是桎梏的凿枘——没有它，桎梏无法锁紧——圣知与仁义，是刑具的核心部件。这比《胠箧》「为之仁义则并与仁义而窃之」更深一层：《胠箧》说仁义被大盗窃取；《在宥》说仁义本身就是刑具的一部分。焉知曾、史之不为桀、跖嚆矢也！——怎么知道曾参、史鱼，不是桀与盗跖的响箭（先导）呢！——「嚆矢」——响箭，比喻先导——曾参、史鱼的极善——是桀与盗跖极恶的先导——这是《在宥》最惊世骇俗的一句：极善，导致极恶——有多高的曾史，就有多深的桀跖。故曰：绝圣弃知，而天下大治。"},{text:"广成子曰：至道之精，窈窈冥冥；至道之极，昏昏默默。无视无听，抱神以静，形将自正。……慎女内，闭女外，多知为败。",tone:"至道",guide:"老聃论撄人心之后，庄子转入第一则寓言——黄帝问广成子。黄帝第一次的问题，是一个治者的问题：如何利用至道来治理天下、养育万民——至道，在黄帝眼中，是一种治理工具。广成子的回答，极为严厉：而所欲问者，物之质也（你想问的，只是事物的表面）；而所欲官者，物之残也（你想管理的，只是事物的末节）——自从你治理天下以来——云气不待族而雨，草木不待黄而落，日月之光益以荒矣——「治天下」，不只伤害人——还伤害了天地自然的运行。黄帝被拒绝之后——退，捐天下，筑特室，席白茅，闲居三月——这是黄帝的转变：从「治天下」，到「捐天下」。三个月后，黄帝再次拜访，问的问题完全变了：「治身奈何而可以长久？」——从「治天下」到「治身」，从外转内，从治人转为治己。广成子蹶然而起，说「善哉问乎！」——两次问，两种回应——问题的方向，决定了能否得到答案。广成子的回答：至道之精，窈窈冥冥；至道之极，昏昏默默——至道，不是可以言说的——只能体验，不能描述。无视无听，抱神以静，形将自正——不是主动去端正形体——而是当你不视不听，抱神以静——形体，自然就端正了。慎女内，闭女外，多知为败——「多知为败」——这一句，是广成子回答的核心——也是对黄帝第一次问题的直接否定：你第一次来，问的是「取天地之精·官阴阳」——那是「多知」——多知，是败。"},{text:"我守其一以处其和。故我修身千二百岁矣，吾形未常衰。",tone:"守一",guide:"我为女遂于大明之上矣，至彼至阳之原也；为女入于窈冥之门矣，至彼至阴之原也——天地有官，阴阳有藏（天地各有其职守，阴阳各有其藏纳之处——这些，不需要你去「官阴阳」）——慎守女身，物将自壮（谨慎守护你自身——万物，将自然壮大——不是你去养育万物，而是你守护自身，万物自然壮大——这是「无为而无不为」在养生层面的体现）——我守其一以处其和（我守住那个「一」，处于阴阳的和谐之中）——故我修身千二百岁矣，吾形未常衰。黄帝再拜稽首曰：「广成子之谓天矣！」广成子最后的话：吾与日月参光，吾与天地为常——人其尽死，而我独存乎！这是广成子的宣言——也是《在宥》对「守其一以处其和」境界的最终描绘：不治天下，不撄人心，不多知——守其一，处其和，慎守其身——与日月参光，与天地为常。"}]}),i[19]||(i[19]=n("h2",{id:"五、云将东游·两遇鸿蒙·心养无为",tabindex:"-1"},[e("五、云将东游·两遇鸿蒙·心养无为 "),n("a",{class:"header-anchor",href:"#五、云将东游·两遇鸿蒙·心养无为","aria-label":'Permalink to "五、云将东游·两遇鸿蒙·心养无为"'},"​")],-1)),i[20]||(i[20]=n("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:x,glossary:p,"default-mode":"classic","aria-label":"在宥·云将问鸿蒙 原文"}),i[21]||(i[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"云将",pinyin:["yún","jiāng"],meaning:"庄子虚构的人物，名字象征「云之将领」，代表有志于治理的人。"},{term:"扶摇之枝",pinyin:["fú","yáo"],meaning:"扶摇：旋风（《逍遥游》中大鹏所乘之风）。扶摇之枝：旋风的旁枝。"},{term:"鸿蒙",pinyin:["hóng","méng"],meaning:"庄子虚构的人物，名字象征混沌初开前的元气状态，代表自然本然之道。"},{term:"拊脾雀跃",pinyin:["fǔ","pí","què","yuè"],meaning:"拊：拍打；脾：大腿。拍打大腿、像雀一样跳跃（无拘无束地嬉游）。"},{term:"倘然止",pinyin:["tǎng","rán"],meaning:"倘然：惊讶、怔住的样子。惊讶地停下来。"},{term:"贽然立",pinyin:["zhì","rán"],meaning:"贽然：恭敬肃立的样子。恭敬地站立。"},{term:"吾弗知",pinyin:["wú","fú","zhī"],meaning:"弗：不。我不知道。"},{term:"游者鞅掌",pinyin:["yāng","zhǎng"],meaning:"鞅掌：繁忙、充实的样子。游者充实自在（游本身就是目的）。"},{term:"以观无妄",pinyin:["yǐ","guān","wú","wàng"],meaning:"以此观照无妄（真实本然）之境。"},{term:"治人之过也",pinyin:["zhì","rén","zhī","guò","yě"],meaning:"这是治理人（干涉人）的过失。"},{term:"毒哉",pinyin:["dú","zāi"],meaning:"毒：危险、有害。太危险了！"},{term:"僊僊乎归矣",pinyin:["xiān","xiān"],meaning:"僊僊：轻盈的样子。轻盈地回去吧！"},{term:"心养",pinyin:["xīn","yǎng"],meaning:"养心！（涵养内心）鸿蒙给云将的全部答案。"},{term:"堕尔形体",pinyin:["duò"],meaning:"堕：放下、忘却。放下你的形体（不执着于形体）。"},{term:"吐尔聪明",pinyin:["tǔ"],meaning:"吐：吐出、放弃。放弃你的聪明（不依赖聪明）。"},{term:"伦与物忘",pinyin:["lún"],meaning:"伦：类别、关系。与万物的关系也一并忘却。"},{term:"大同乎涬溟",pinyin:["xìng","míng"],meaning:"涬溟：混沌无形的元气状态。与混沌无形的元气大同。"}]}),i[22]||(i[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"意！心养！汝徒处无为，而物自化",subtitle:"在宥天下，不是一种政策——而是一种内在状态：养心，无为，不知，不问——万物，自然生长。",lines:[{text:"鸿蒙拊脾雀跃不辍，对云将曰：游！",tone:"本然",guide:"云将东游，过扶摇之枝而适遭鸿蒙。鸿蒙方将拊脾雀跃而游——鸿蒙正在拍着大腿、像雀一样跳跃着嬉游。云将见之，倘然止，贽然立（被震撼，恭敬地站立），问：叟何人邪？叟何为此？鸿蒙的回答只有一个字：「游！」——我在此，只是游。这是鸿蒙第一次亮相——本然状态，就是「游」——无目的、无追求、自在嬉游。"},{text:"云将曰：天气不和，地气郁结，六气不调，四时不节。今我愿合六气之精以育群生，为之奈何？鸿蒙拊脾雀跃掉头曰：吾弗知！吾弗知！",tone:"弗知",guide:"云将的问，是一个治者之问：天气不和、地气郁结、六气不调、四时不节——我愿合六气之精以育群生，为之奈何？鸿蒙拊脾雀跃掉头曰：吾弗知！吾弗知！——我不知道！我不知道！这与第4段广成子拒绝黄帝第一次问完全呼应：治者之问，无答案——因为「治」这个方向本身就错了。鸿蒙的「吾弗知」，不是谦虚，不是逃避——而是：这个问题，不值得回答——因为它预设了一个错误的方向。"},{text:"鸿蒙曰：意！心养！汝徒处无为，而物自化。堕尔形体，吐尔聪明，伦与物忘，大同乎涬溟。解心释神，莫然无魂。",tone:"心养",guide:"云将不得问。又三年，东游，再遇鸿蒙。云将曰：天忘朕邪？——您忘记我了吗？鸿蒙说：浮游不知所求，猖狂不知所往，游者鞅掌，以观无妄——朕又何知！云将说：朕也自以为猖狂，而民随予所往；朕也不得已于民，今则民之放也！愿闻一言——这是云将的转变：从「合六气之精以育群生」的治者之问，到「民之放也」的困惑——他意识到了自己的问题。鸿蒙说：乱天之经，逆物之情——治人之过也。云将再问，鸿蒙终于给出答案：意！心养！——养心！汝徒处无为，而物自化（你只管处于无为的状态，万物自然化育）——堕尔形体（放下对身体的执着），吐尔聪明（放弃对聪明的依赖），伦与物忘（放下与万物的关系），大同乎涬溟（与混沌元气大同）——解心释神，莫然无魂。「心养」——全篇最核心的实践命题——不是积累，不是修炼，不是变得更好——而是：减少，放下，忘却，回归。"},{text:"万物云云，各复其根，各复其根而不知。浑浑沌沌，终身不离。若彼知之，乃是离之。无问其名，无窥其情，物固自生。",tone:"若知即离",guide:"万物云云，各复其根，各复其根而不知——万物各自回归自己的本根，却不知道自己在回归。浑浑沌沌，终身不离——浑浑沌沌，终身不离开（本然）。若彼知之，乃是离之——如果他知道（意识到）这个状态，就已经离开这个状态了——这是《在宥》最深的认识论命题：道，不可以被「知道」。你一旦「知道」了自己是什么人——你就开始按照那个标签行动——你就离开了本然的自己。无问其名，无窥其情，物固自生——不要问它的名字，不要窥探它的实情——万物，本来就自然生长。你，本来就是你——不需要知道自己的名字，不需要窥探自己的实情——你，本来就自然生长。云将曰：天降朕以德，示朕以默。躬身求之，乃今得也。"}]}),i[23]||(i[23]=n("h2",{id:"六、有土者大物·大人之教·天道人道",tabindex:"-1"},[e("六、有土者大物·大人之教·天道人道 "),n("a",{class:"header-anchor",href:"#六、有土者大物·大人之教·天道人道","aria-label":'Permalink to "六、有土者大物·大人之教·天道人道"'},"​")],-1)),i[24]||(i[24]=n("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:b,glossary:z,"default-mode":"classic","aria-label":"在宥·有土者大物 原文"}),i[25]||(i[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"有大物也",pinyin:["yǒu","dà","wù","yě"],meaning:"拥有大物（国家·天下这样的大东西）。"},{term:"不可以物",pinyin:["bù","kě","yǐ","wù"],meaning:"不可以用对待普通事物的方式来对待（不可以被物所役使）。"},{term:"出入六合",pinyin:["liù","hé"],meaning:"六合：上下四方，即整个宇宙空间。出入于宇宙之间。"},{term:"有问而应之",pinyin:["yǒu","wèn","ér","yìng","zhī"],meaning:"有问才回应（不主动教化）。"},{term:"处乎无响",pinyin:["chǔ","hū","wú","xiǎng"],meaning:"处于无声无响的状态。"},{term:"行乎无方",pinyin:["xíng","hū","wú","fāng"],meaning:"行于无固定方向的状态。"},{term:"大同而无己",pinyin:["dà","tóng","ér","wú","jǐ"],meaning:"大同之中，没有自我（小我消融）。"}]}),i[26]||(i[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"物而不物，故能物物",subtitle:"接触事物，但不被事物所役使——保持内在的自由，才能真正地主宰事物。",lines:[{text:"世俗之人，皆喜人之同乎己而恶人之异于己也。同于己而欲之，异于己而不欲者，以出乎众为心也。夫以出乎众为心者，曷常出乎众哉？",tone:"出众",guide:"第六段，从寓言回到议论——但这一次，议论的对象，从「治天下」转向了「有土者」——拥有土地、统治国家的人。开篇，庄子先描绘世俗之人的心理——皆喜人之同乎己而恶人之异于己（都喜欢别人与自己相同，厌恶别人与自己不同）——以出乎众为心（以超出众人为内心的目标）——夫以出乎众为心者，曷常出乎众哉？（但以超出众人为目标的人，哪里真正超出过众人呢？）。这三句，是对「以出乎众为心」这种心态的精准批判：想要超出众人的人——反而最依赖众人的认可——因为他的「超出」，是以众人为参照的——没有众人，他的「超出」就失去了意义——所以他永远无法真正超出众人。这与第5段鸿蒙「浮游不知所求，猖狂不知所往」完全对照：真正的「超出」，是不知所求、不知所往——不以众人为参照，不以「出众」为目标——这，才是真正的独有。"},{text:"而欲为人之国者，此揽乎三王之利而不见其患者也。此以人之国侥幸也。几何侥幸而不丧人之国乎？其存人之国也，无万分之一；而丧人之国也，一不成而万有余丧矣！悲夫，有土者之不知也！",tone:"侥幸",guide:"从世俗之人，庄子转向「欲为人之国者」——想要治理别人国家的人——此揽乎三王之利而不见其患者也（这是贪取三王的利益，却看不见其中祸患的人）——此以人之国侥幸也（这是用别人的国家来侥幸冒险）——几何侥幸而不丧人之国乎（能有几次侥幸而不丧失别人的国家呢）——其存人之国也，无万分之一（能保存别人国家的可能，连万分之一都没有）——而丧人之国也，一不成而万有余丧矣（而使别人国家灭亡的，一次不成功就有万余次的丧失）——悲夫，有土者之不知也！这一段，是庄子对「治国者」最冷静的概率分析：治国，不是一件成功率高的事——存国的概率：万分之一；丧国的概率：万余倍——但治国者，都以为自己是那个万分之一——这，是「以人之国侥幸」——用别人的国家来赌自己的运气。"},{text:"夫有土者，有大物也。有大物者，不可以物。物而不物，故能物物。明乎物物者之非物也，岂独治天下百姓而已哉！出入六合，游乎九州，独往独来，是谓独有。独有之人，是之谓至贵。",tone:"物而不物",guide:"从批判，庄子转入正面的建构——夫有土者，有大物也（拥有土地的人，拥有的是「大物」——国家·天下，是最大的「物」）——有大物者，不可以物（拥有大物的人，不可以用对待普通事物的方式来对待它——不可以被大物所役使）——物而不物，故能物物（对待事物，但不被事物所役使——所以才能主宰万物，使万物各得其所）。这三句，是《在宥》对「有土者」最深的建议：「物而不物」——不是不接触事物，不是不管事物——而是：接触事物，但不被事物所定义、所役使——保持内在的自由，才能真正地主宰事物。「物物」——使万物各得其所——不是强制管理，而是让万物自然各归其位。明乎物物者之非物也——明白「使万物各得其所的人」本身不是物——出入六合，游乎九州，独往独来，是谓独有——独有之人，是之谓至贵——「独有」——不是独占财富，不是独揽权力——而是：独自拥有道，独自保有本性——不依赖他人，不被外物役使——这，才是真正的「至贵」。"},{text:"大人之教，若形之于影，声之于响，有问而应之，尽其所怀，为天下配。",tone:"大人之教",guide:"大人之教——得道之人的教化——若形之于影，声之于响（像形体与影子的关系，像声音与回响的关系）——这两个比喻，极为精准：形与影——形动，影自然随——形，不需要主动去「教」影如何动；声与响——声发，响自然应。大人之教，就是这样——不主动教化，不强制传授——有问而应之——有人问，才回应——不问，就沉默——尽其所怀，为天下配——充分回应问者所怀抱的，与天下相配合。这与第4段广成子「善哉问乎」完全呼应：广成子拒绝了黄帝第一次的问题——因为那个问题，不是真正的问——第二次，黄帝真正问了，广成子才回应——这，就是「有问而应之」。"},{text:"睹有者，昔之君子；睹无者，天地之友。",tone:"有与无",guide:"颂论形躯，合乎大同（与万物一体相合）——大同而无己（大同之中，没有自我——小我消融）——无己，恶乎得有有（没有自我，哪里还有「有」——执着于有）——睹有者，昔之君子（看到「有」——执着于有形有名——的人，是过去的君子——儒家的君子，执着于有：有仁义，有礼法，有名分——君子，停留在「有」的层面）；睹无者，天地之友（看到「无」——通达于无形无名——的人，是天地的朋友——通达于无：无己，无执，无名——与天地同游，与道同在——这，才是《在宥》真正肯定的境界）。「无己」——这是《逍遥游》「至人无己」的回响——无己，不是消灭自我——而是：小我消融于大同之中——不再执着于「我」与「非我」的分别。"},{text:"何谓道？有天道，有人道。无为而尊者，天道也；有为而累者，人道也。主者，天道也；臣者，人道也。天道之与人道也，相去远矣，不可不察也。",tone:"天道人道",guide:"《在宥》全篇，以这五句作结——何谓道？有天道，有人道——无为而尊者，天道也（无为而自然尊贵的，是天道——日月运行，四时更替，万物生长——没有一件是「有为」的，但没有一件不尊贵）；有为而累者，人道也（有为而带来拖累的，是人道——尧股无胈，胫无毛——这，就是「有为而累」的具体体现）；主者，天道也；臣者，人道也（天道是主，人道是臣——人道，应当服从天道——有为，应当服从无为——治天下，应当服从在宥天下）。天道之与人道也，相去远矣，不可不察也——「不可不察」——这四个字，是《在宥》送给每一个「有土者」的最后警示：你，分清楚了吗？你现在做的，是天道，还是人道？是无为而尊，还是有为而累？是主，还是臣？"}]}),i[27]||(i[27]=f(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·立（在宥天下·不闻治天下）</span></span>
<span class="line"><span>    在之也者恐天下淫其性·宥之也者恐天下迁其德</span></span>
<span class="line"><span>    → 全篇命题：在宥天下，不闻治天下</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·析（撄人心之害·喜怒失位·赏罚不给）</span></span>
<span class="line"><span>    大喜毗阳大怒毗阴·喜怒失位·天下之大不足以赏罚</span></span>
<span class="line"><span>    → 治天下的行为，伤害人心与本性</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·论（八者存亡·无为临天下）</span></span>
<span class="line"><span>    八者存可也亡可也·君子不得已莫若无为·尸居龙见</span></span>
<span class="line"><span>    → 无为，然后安其性命之情</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第4段·证（老聃论撄人心·黄帝问广成子）</span></span>
<span class="line"><span>    女慎无撄人心·罪在撄人心·守其一以处其和</span></span>
<span class="line"><span>    → 从历史证明：撄人心是罪，守一是道</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第5段·证（云将东游·两遇鸿蒙·心养无为）</span></span>
<span class="line"><span>    心养·汝徒处无为而物自化·若彼知之乃是离之·物固自生</span></span>
<span class="line"><span>    → 心养无为的实践：万物自然生长</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第6段·合（有土者大物·大人之教·天道人道）</span></span>
<span class="line"><span>    物而不物故能物物·有问而应之·无为而尊者天道也</span></span>
<span class="line"><span>    → 全篇收束：天道为主，人道为臣，不可不察</span></span></code></pre></div><p><strong>全篇主线</strong>：从「在宥天下」的命题立起，析撄人心之害，论八者存亡与无为临天下，经老聃论撄心、广成子守一、鸿蒙心养的双重印证，最终收于「天道人道相去远矣」——治天下，先养心。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-「在宥天下」究竟是什么意思" tabindex="-1">第一问：「在宥天下」究竟是什么意思？ <a class="header-anchor" href="#第一问-「在宥天下」究竟是什么意思" aria-label="Permalink to &quot;第一问：「在宥天下」究竟是什么意思？&quot;">​</a></h3><p>「在宥」二字，是全篇的核心，也是最容易被误解的地方。</p><p>常见的误解有两种：误解一——在宥 = 放任不管（认为庄子主张什么都不做，任由天下自生自灭——这是把「在宥」等同于「消极无为」）；误解二——在宥 = 宽松管理（认为庄子只是主张少管一点，用更温和的方式治理——这是把「在宥」等同于「软性治理」）。</p><p>庄子的本意，两者都不是。回到原文：「在之也者，恐天下之淫其性也；宥之也者，恐天下之迁其德也。」「在宥」的动机，是「恐」——是担心，是保护——在：担心天下的本性被扰乱，所以让其自在；宥：担心天下的本德被改变，所以宽容不干涉。</p><p>「在宥」，是一种积极的保护——不是消极地不管，而是：主动地保护本性不被干涉——这种保护，以「不干涉」的方式实现。</p><p>一个比喻：一棵树，在土地里自然生长——「在宥」，是保护这棵树不被人随意修剪、移植、嫁接——不是不给它浇水，不是不给它阳光——而是：不去改变它本来的生长方向。「治天下」，是修剪——按照人的想法，把树修成某种形状——看起来更整齐，更有秩序——但树，失去了本来的形状。「在宥天下」，是不修剪——让树按照自己的方式生长——可能不整齐，可能不符合人的审美——但树，是本然的。</p><h3 id="第二问-「撄人心」为什么是罪" tabindex="-1">第二问：「撄人心」为什么是罪？ <a class="header-anchor" href="#第二问-「撄人心」为什么是罪" aria-label="Permalink to &quot;第二问：「撄人心」为什么是罪？&quot;">​</a></h3><p>老聃说：「罪在撄人心。」这是《在宥》最具争议的命题——因为它把一切「治理」都定性为「撄人心」，把一切「撄人心」都定性为「罪」。</p><p>理解这个命题，需要先理解老聃对「人心」的描述：「偾骄而不可系者，其唯人心乎！」人心，是天地间最不可控的存在——柔软时无坚不摧，锋利时无物不伤，热时焦火，冷时凝冰，快时瞬息万里。</p><p>「撄人心」的问题，不在于动机——黄帝以仁义撄人心，动机是好的；尧舜股无胈、胫无毛，牺牲是真实的——但结果，是天下大乱。为什么好的动机，带来坏的结果？庄子的逻辑是：撄人心（无论动机好坏）→ 人心被激发（超出本然节度）→ 喜怒失位·居处无常·思虑不自得 → 本性失衡·向两个极端分化 → 一端：盗跖（极恶），一端：曾史（极善）→ 极善激发极恶（曾史是桀跖嚆矢）→ 儒墨毕起·斤锯绳墨椎凿 → 天下脊脊大乱。</p><p>「撄人心」是罪，不是因为动机坏——而是因为：任何对人心的激发，都会打破人心本然的平衡——而打破平衡之后，没有任何力量能够重新控制它——因为人心，偾骄而不可系。这是一个系统性的命题：你激发了人心的善——人心的恶，也同时被激发——因为善与恶，是同一个失衡的两面——你无法只激发善，不激发恶——这，是「撄人心」最深的危险。所以老聃说：「女慎，无撄人心。」不是「你要激发善的一面」——而是：根本不要去撄它。</p><h3 id="第三问-「心养」在今天意味着什么" tabindex="-1">第三问：「心养」在今天意味着什么？ <a class="header-anchor" href="#第三问-「心养」在今天意味着什么" aria-label="Permalink to &quot;第三问：「心养」在今天意味着什么？&quot;">​</a></h3><p>鸿蒙给云将的答案，只有两个字：「心养。」然后展开：「汝徒处无为，而物自化。堕尔形体，吐尔聪明，伦与物忘，大同乎涬溟。解心释神，莫然无魂。」</p><p>「心养」，不是心理治疗，不是冥想课程——它是一种根本性的生命态度：堕尔形体（放下对身体的执着——不以形体为自我）；吐尔聪明（放弃对聪明的依赖——不以智识为资本）；伦与物忘（放下与万物的关系——不以关系定义自我）；大同乎涬溟（与混沌元气大同——回到本然）。四个「放下」，是「心养」的具体内容——不是积累，不是修炼，不是变得更好——而是：减少，放下，忘却，回归。</p><p>在今天，「心养」面对的是什么？今天的「撄人心」，比庄子时代更密集、更精准：信息流——每一条推送，都在撄你的心——激发你的喜怒，激发你的欲望，激发你的恐惧；绩效评估——每一个KPI，都在撄你的心——让你的喜怒，与数字挂钩；社交比较——每一次点赞，都在撄你的心——「以出乎众为心」。</p><p>「心养」，在今天意味着：信息流不断激发喜怒→堕尔形体——不以情绪反应为自我；绩效指标定义价值→吐尔聪明——不以外部评价为依据；社交比较制造焦虑→伦与物忘——不以关系和比较定义自我；永远在线·永远响应→处乎无响·行乎无方——不必永远在线；追求更多·更快·更好→物固自生——万物本来就自然生长。</p><p>「心养」，不是逃避——不是关掉手机，不是辞职隐居——而是：在参与一切的同时，不被一切所役使——「物而不物，故能物物」——接触事物，但不被事物定义——这，才是今天「心养」的真实意涵。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p><strong>领导力：从「治」到「在宥」</strong></p><blockquote><p>《在宥》对「治天下」的批判，在今天的管理与领导力语境中，极具启发。庄子的命题：「有大物者，不可以物。物而不物，故能物物。」翻译成今天的语言：管理大组织的人，不能被组织所役使；接触事务但不被事务定义，才能真正主导事务。「在宥」式的领导力，有三个特征：第一·有问而应，不主动干涉——「大人之教，若形之于影，声之于响，有问而应之」——不主动推行自己的想法，等待真正的问题出现，再充分回应——这不是懒惰，而是尊重——尊重每个人找到自己答案的过程。第二·贵以身，爱以身——「贵以身于为天下，则可以托天下」——真正可以被托付的领导者，不是那种「以天下为己任」、舍身忘我的人——而是那种珍视自身本性的人——因为珍视自身本性的人，才懂得珍视他人的本性。第三·不得已而临莅，莫若无为——「故君子不得已而临莅天下，莫若无为」——真正的领导者，是「不得已」才去领导的——不是主动争取权力，而是在不得已的情况下承担责任——这种「不得已」，保证了领导者不会把权力当成目的。</p></blockquote><p><strong>教育：从「撄心」到「心养」</strong></p><blockquote><p>《在宥》对「撄人心」的批判，对今天的教育有深刻的启示。今天的教育，大量是「撄心」的：排名与竞争——激发孩子的喜怒，让他们的自我价值与成绩挂钩——这是「撄人心」最典型的形式；标准答案——告诉孩子什么是对的，什么是错的——这是「迁其德」——改变本真之德。「说仁邪，是乱于德也；说义邪，是悖于理也」——当我们不断告诉孩子「你要善良·你要勤奋·你要有责任感」——我们以为在培养德性——实则，是在「乱于德」——因为真正的德，不是被告知的，而是本然流出的。「心养」式的教育，意味着：不激发，而保护——不灌输，而等待——不比较，而允许——让本性，自然流淌。这不是放任，而是：相信每个孩子，都有「物固自生」的力量——你只需要，不去阻碍它。</p></blockquote><p><strong>自我：从「多知为败」到「若彼知之乃是离之」</strong></p><blockquote><p>《在宥》对「知」的批判，在今天的信息时代，有特别的意义。广成子说「多知为败」——今天，我们每天接收的信息量，是庄子时代的人一生都无法想象的——我们，活在「多知」的极端状态里。但更深的问题，是鸿蒙说的：「若彼知之，乃是离之。」我们不只是知得太多——我们还在不断地「知道自己」——MBTI测试、心理咨询、自我分析——我们用各种工具，去「知道」自己是什么人——但鸿蒙说：你一旦「知道」了——你就离开了。你「知道」自己是INTJ——你就开始按照INTJ的方式行动——你就离开了本然的自己。「浑浑沌沌，终身不离」——不是说不要了解自己——而是说：不要把「了解自己」变成一个固定的标签——因为本然的自己，是浑浑沌沌的，是流动的，是不可固定的——任何固定，都是离开。「无问其名，无窥其情，物固自生」——你，本来就是你——不需要知道自己的名字，不需要窥探自己的实情——你，本来就自然生长。</p></blockquote><p><strong>政治哲学：天道与人道的现代意义</strong></p><blockquote><p>《在宥》最后的命题：「无为而尊者，天道也；有为而累者，人道也。主者，天道也；臣者，人道也。」这个命题，在今天的政治哲学语境中，可以这样理解：天道——系统的自组织能力——任何复杂系统（生态·市场·社会），都有自组织的能力——不需要外力强制，系统会自然找到平衡——这，是「无为而尊」的天道。人道——外力的干预——当人用外力干预系统——无论动机多好，都会带来「累」——因为系统的复杂性，远超人的认知能力——这，是「有为而累」的人道。庄子不是说「永远不干预」——他说的是：「主者，天道也；臣者，人道也」——干预，应当服从系统的自组织逻辑——人道，应当是天道的臣，而不是天道的主。今天，这个命题的意义在于：在任何管理与治理中——先问：这个系统的「天道」是什么？它的自组织逻辑是什么？我的干预，是在顺应这个逻辑，还是在违背它？「不可不察也。」</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>在宥</td><td>第1段</td><td>全篇核心词。在：自在，让其自在；宥：宽容，不加干涉。「在宥天下」：以不干涉的方式，保护天下的本性不被扰乱、不被改变</td></tr><tr><td>淫其性</td><td>第1段</td><td>扰乱、过度刺激本性，使本性失去自然节度。非「放纵本性」，而是「本性被外力过度激发」</td></tr><tr><td>迁其德</td><td>第1段</td><td>改变、迁移本真之德，使德不再是自己的德</td></tr><tr><td>性命之情</td><td>第2·3段</td><td>本性与生命的真实情感，本然的生命状态。非被激发的喜怒，非被规范的善恶</td></tr><tr><td>撄人心</td><td>第2·4段</td><td>扰乱、触动人心，使人心超出本然节度。老聃的核心警告：「女慎，无撄人心。」无论动机好坏，撄人心都会导致人心失衡，天下大乱</td></tr><tr><td>偾骄而不可系</td><td>第4段</td><td>奔腾不驯而无法束缚。描述人心的本质——最强大、最不可控</td></tr><tr><td>嚆矢</td><td>第4段</td><td>响箭，比喻先导、开端。「曾史是桀跖嚆矢」——极善，是极恶的先导</td></tr><tr><td>绝圣弃知</td><td>第4段</td><td>断绝圣人之道，抛弃机巧之知。《胠箧》与《在宥》共同的核心命题</td></tr><tr><td>窈窈冥冥·昏昏默默</td><td>第4段</td><td>描述至道的性质：深远幽暗、混沌沉默、不可言说、不可测度。至道，只能处于其中，不能被「知道」</td></tr><tr><td>多知为败</td><td>第4段</td><td>过多的知识是失败的根源。广成子对黄帝的核心教导</td></tr><tr><td>守其一以处其和</td><td>第4段</td><td>守住那个「一」（道的本体），处于阴阳的和谐之中。广成子修身千二百岁的根本方法</td></tr><tr><td>心养</td><td>第5段</td><td>全篇最核心的实践命题。养心，涵养内心。鸿蒙给云将的全部答案。具体内容：堕形体·吐聪明·伦与物忘·大同乎涬溟·解心释神·莫然无魂</td></tr><tr><td>若彼知之，乃是离之</td><td>第5段</td><td>如果他知道（意识到）这个状态，就已经离开这个状态了。《在宥》最深的认识论命题：道，不可以被「知道」</td></tr><tr><td>物固自生</td><td>第5段</td><td>万物本来就自然生长。不需要你去养育万物，万物本来就自然生长</td></tr><tr><td>物而不物，故能物物</td><td>第6段</td><td>接触事物但不被事物役使，所以才能主宰万物使其各得其所</td></tr><tr><td>独有</td><td>第6段</td><td>独自拥有道，独自保有本性，不依赖他人，不被外物役使。《在宥》对最高境界的命名</td></tr><tr><td>睹有者·睹无者</td><td>第6段</td><td>睹有者：执着于有形有名，是「昔之君子」（儒家君子）；睹无者：通达于无形无名，是「天地之友」</td></tr><tr><td>天道·人道</td><td>第6段</td><td>天道：无为而尊，是主；人道：有为而累，是臣。全篇收束的核心对立</td></tr></tbody></table><h3 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h3><p>如果《在宥》全篇，只能用一句话来总结——</p><blockquote><p><strong>「意！心养！汝徒处无为，而物自化。」</strong></p></blockquote><p>如果只能用一个问题来收束——</p><blockquote><p><strong>「天道之与人道也，相去远矣——你，分清楚了吗？」</strong></p></blockquote><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·外篇·在宥》</li></ul>`,40))])}}});export{C as __pageData,v as default};
